DefaultEnglishWords.push(...[{"_id":"builtin-en-zsb-00731","word":"for the moment","type":"短语","phonetic":"","meaning":"现在，暂时","example":"For the moment, we have no news about the exam results. / 目前我们还没有考试结果的消息。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00732","word":"for the sake of","type":"短语","phonetic":"","meaning":"为了…起见","example":"He gave up smoking for the sake of his family. / 为了家人，他戒了烟。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00733","word":"fortunate","type":"形容词","phonetic":"/'fɔ:ʧənit/","meaning":"幸运的, 幸福的","example":"We were fortunate to get the last two tickets. / 我们很幸运，买到了最后两张票。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00734","word":"fortune","type":"名词","phonetic":"/'fɔ:ʧən/","meaning":"财富; 运气, 好运, 命运","example":"He made a big fortune by selling fruit online. / 他靠网上卖水果发了大财。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00735","word":"forty","type":"数词","phonetic":"/'fɔ:ti/","meaning":"四十","example":"About forty students took part in the singing contest. / 大约有四十名学生参加了歌唱比赛。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00736","word":"forward","type":"形容词","phonetic":"/'fɔ:wəd/","meaning":"早的, 迅速的, 前进的; adv.向前地,向将来","example":"We are looking forward to the summer holiday. / 我们正期待着暑假的到来。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00737","word":"found","type":"动词","phonetic":"/faund/","meaning":"建立, 创立","example":"The school was founded more than a hundred years ago. / 这所学校创建于一百多年前。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00738","word":"four","type":"数词","phonetic":"/fɔ:/","meaning":"四, 四个","example":"Four of my classmates come from the same small town. / 我的同学中有四个来自同一个小镇。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00739","word":"fourteen","type":"数词","phonetic":"/'fɔ:'ti:n/","meaning":"十四","example":"She is fourteen years old and studies in Grade Nine. / 她十四岁，读九年级。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00740","word":"fourth","type":"数词","phonetic":"/fɔ:θ/","meaning":"第四个","example":"Our classroom is on the fourth floor of that building. / 我们的教室在那栋楼的四楼。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00741","word":"free","type":"形容词","phonetic":"/fri:/","meaning":"1. 自由的 2. 免费的, 免税的 3. 空闲的 4. (from.of)没有…的，免去…的 vt. (from, of)释放, 使自由","example":"The concert is free for students, so let us go together. / 这场音乐会对学生免费，我们一起去吧。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00742","word":"freedom","type":"名词","phonetic":"/'fri:dəm/","meaning":"自由, 自主, 直率, 特权","example":"Students enjoy more freedom to choose their courses now. / 现在学生享有更多选择课程的自由。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00743","word":"freeze","type":"动词","phonetic":"/fri:z/","meaning":"(使)结冰, (使)冷冻","example":"Water will freeze when the temperature drops below zero. / 温度降到零度以下时水会结冰。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00744","word":"French","type":"名词","phonetic":"/frenʧ/","meaning":"法国人, 法语; adj. 法国的, 法国人的,法语的","example":"She is learning French because she wants to study in Paris. / 她正在学法语，因为她想去巴黎留学。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00745","word":"fresh","type":"形容词","phonetic":"/freʃ/","meaning":"1. 新鲜的 2. 新的，新近的 3. 清新的，淡的 4. 鲜艳的","example":"We can buy fresh vegetables at the market near our school. / 我们可以在学校附近的市场买到新鲜蔬菜。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00746","word":"Friday","type":"名词","phonetic":"/'fraidi/","meaning":"星期五","example":"We will have a class meeting this Friday afternoon. / 这个星期五下午我们将开班会。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00747","word":"friend","type":"名词","phonetic":"/frend/","meaning":"朋友","example":"A good friend will listen to you when you are sad. / 好朋友会在你难过的时候听你倾诉。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00748","word":"friendly","type":"形容词","phonetic":"/'frendli/","meaning":"友好的, 友谊的","example":"Our new neighbors are friendly and often help us. / 我们的新邻居很友好，经常帮助我们。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00749","word":"friendship","type":"名词","phonetic":"/'frendʃip/","meaning":"友谊, 友好","example":"True friendship is more valuable than money. / 真正的友谊比金钱更有价值。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00750","word":"frighten","type":"及物动词","phonetic":"/'fraitn/","meaning":"使惊吓","example":"The loud noise outside frightened the little baby. / 外面的大声响吓到了那个小婴儿。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00751","word":"from","type":"介词","phonetic":"/frəm/","meaning":"1. 从，自，从…来 2. 由于 3. (表示去除，免掉，阻止等)4. (表示识别，区别)","example":"She comes from a small village in the south. / 她来自南方的一个小村庄。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00752","word":"front","type":"形容词","phonetic":"/frʌnt/","meaning":"前面的，前部的 n. 1. 前面 2. 前线 vt. 面对, 朝向","example":"Students must write their names on the front page of the paper. / 请把你的名字写在这份文件的前页。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00753","word":"fruit","type":"名词","phonetic":"/fru:t/","meaning":"水果, 果实, 果类 2. 成果","example":"Eating fruit every day is good for your health. / 每天吃水果对你的健康有好处。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00754","word":"fulfil(l)","type":"及物动词","phonetic":"/ful'fil/","meaning":"1. 实践, 履行 2. 完成","example":"He worked hard to fulfill his dream of becoming a teacher. / 他努力实现成为教师的梦想。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00755","word":"full","type":"形容词","phonetic":"/ful/","meaning":"1.（of）充满的 2. 完全的, 丰富的","example":"The bus was full, so we had to wait for the next one. / 公交车满了，我们只好等下一辆。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00756","word":"fun","type":"名词","phonetic":"/fʌn/","meaning":"1. 娱乐, 玩笑, 嬉笑; 有趣的人或事物","example":"We had a lot of fun at the school party last night. / 昨晚的学校派对上我们玩得很开心。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00757","word":"funny","type":"形容词","phonetic":"/'fʌni/","meaning":"有趣的, 好笑的, 滑稽的","example":"He told a funny story and made the whole class laugh. / 他讲了一个有趣的故事，逗得全班大笑。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00758","word":"further","type":"形容词","phonetic":"/'fə:ðə/","meaning":"更远的, 更多的, 深一层的 adv. 1. 更进一步地, 更远地 2. 此外","example":"For further information, please call the number below. / 如需更多信息，请拨打下面的电话。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00759","word":"future","type":"名词","phonetic":"/'fju:ʧə/","meaning":"未来, 将来, 前途, 远景; adj.未来的, 将来的","example":"It is obvious that hard work today will shape our future. / 很明显，今天的努力会塑造我们的未来。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00760","word":"gain","type":"动词","phonetic":"/gein/","meaning":"1.获得，博得 2.增加，（钟，表）走得快 n.收益，得益","example":"Students can gain a lot of experience from part-time jobs. / 学生能从兼职工作中学到很多经验。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00761","word":"game","type":"名词","phonetic":"/geim/","meaning":"1.娱乐，游戏 2.比赛 3.(pl.)运动会","example":"The basketball game will start at four this afternoon. / 篮球比赛将在今天下午四点开始。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00762","word":"garage","type":"名词","phonetic":"/'gærɑ:ʒ/","meaning":"汽车间, 修车厂, 车库","example":"My father is cleaning the garage on Saturday morning. / 我爸爸星期六早上在打扫车库。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00763","word":"garden","type":"名词","phonetic":"/'gɑ:dn/","meaning":"(菜、花)园, 花园","example":"My mother grows tomatoes and roses in our garden. / 我妈妈在我们的花园里种西红柿和玫瑰。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00764","word":"gas","type":"名词","phonetic":"/gæs/","meaning":"气体, 煤气, 毒气, 汽油,","example":"Remember to turn off the gas after you finish cooking. / 做完饭请把煤气关掉。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00765","word":"gate","type":"名词","phonetic":"/geit/","meaning":"大门","example":"We waited for our teacher at the school gate. / 我们在校门口等老师。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00766","word":"gather","type":"动词","phonetic":"/'gæðə/","meaning":"1.聚集，聚拢 2.收集","example":"Many people gathered in the square to watch the show. / 许多人聚集在广场上看表演。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00767","word":"gather in","type":"短语","phonetic":"","meaning":"收获（庄稼）","example":"The farmers will gather in the rice before the rain comes. / 农民们会在下雨前把稻子收进来。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00768","word":"gay","type":"形容词","phonetic":"/gei/","meaning":"1.同性恋者的 2.色彩鲜艳的 3.愉快的 n.（尤指男）同性恋者","example":"The room was gay with lights and flowers for the festival. / 为了过节，房间里挂满了灯和鲜花，显得十分鲜艳。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00769","word":"general","type":"形容词","phonetic":"/'ʤenərəl/","meaning":"1.一般的，普通的 2.总的，大体的 n.将军","example":"The general idea of the plan is easy to understand. / 这个计划的大体思路很容易理解。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00770","word":"generally speaking","type":"短语","phonetic":"","meaning":"（相当于 in general）通常, 大体上","example":"Generally speaking, young people learn new apps faster than older ones. / 一般来说，年轻人比年长者更快学会新应用。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00771","word":"generation","type":"名词","phonetic":"/ˌʤenə'reiʃən/","meaning":"1.产生, 发生 2.一代, 一代人","example":"The older generation often worries about the habits of young people. / 年长的一代常常担心年轻人的习惯。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00772","word":"gentle","type":"形容词","phonetic":"/'ʤentl/","meaning":"1.有礼貌的, 文雅的 2. 温和的，柔和的","example":"The nurse spoke in a gentle voice to the nervous child. / 护士用温和的声音对那个紧张的孩子说话。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00773","word":"gentleman","type":"名词","phonetic":"/'ʤentlmən/","meaning":"阁下, 先生, 有身份的人, 绅士; 男厕所, 男盥洗室","example":"A gentleman always helps others and never shouts in public. / 绅士总是帮助别人，从不在公共场合大喊大叫。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00774","word":"gently","type":"副词","phonetic":"/'ʤɛntli/","meaning":"文雅地, 有礼貌地","example":"She closed the door gently so as not to wake the baby. / 她轻轻地关上门，以免吵醒宝宝。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00775","word":"geography","type":"名词","phonetic":"/ʤi'ɔgrəfi/","meaning":"地理学, 地理","example":"Geography is my favorite subject because I like maps. / 地理是我最喜欢的科目，因为我喜欢地图。","folder":"专升本词汇","level":"专升本","tags":["专升本","专升本高频"]},{"_id":"builtin-en-zsb-00776","word":"get","type":"及物动词","phonetic":"/get/","meaning":"1.获得，得到 2.使得，把…弄得 vi. 1.变得，成为 2.（to）到达","example":"You can get more information about the course on the website. / 你可以在网站上获得关于这门课程的更多信息。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00777","word":"get along/on","type":"短语","phonetic":"","meaning":"有进展，有进步","example":"How do you get on with your English study these days? / 你最近的英语学习进展如何？","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00778","word":"get along/on with","type":"短语","phonetic":"","meaning":"1.在…方面获得成功，在…方面取得进展 2.和……相处","example":"It is important to get along with the people around you. / 与周围的人和睦相处很重要。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00779","word":"get at","type":"短语","phonetic":"","meaning":"1.达到，够着 2.意思是","example":"The box is too high for me to get at. / 那个箱子太高了，我够不着。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00780","word":"get by","type":"短语","phonetic":"","meaning":"通过，勉强混过","example":"With little money, they had to get by on simple food. / 钱很少，他们只能靠简单的食物勉强过日子。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00781","word":"get down","type":"短语","phonetic":"","meaning":"1.(to sth./doing sth.)开始做某事；重视某事物；认真处理某事 2.写下","example":"Let us get down to work as soon as the meeting ends. / 会议一结束我们就开始工作吧。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00782","word":"get in","type":"短语","phonetic":"","meaning":"1.到达目的地 2.收获，收集","example":"What time does your flight get in tomorrow? / 你明天的航班什么时候到达？","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00783","word":"get into","type":"短语","phonetic":"","meaning":"1.进入 2.陷入","example":"It is easy to get into trouble if you never plan ahead. / 如果从不提前计划，很容易陷入麻烦。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00784","word":"get off","type":"短语","phonetic":"","meaning":"1.从…下来 2.脱离，离开，动身","example":"Please get off the bus at the next stop. / 请在下一站下车。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00785","word":"get over","type":"短语","phonetic":"","meaning":"1.从…中恢复过来 2.克服 3.度过，结束","example":"It took him a month to get over the bad cold. / 他花了一个月才从重感冒中恢复过来。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00786","word":"get rid of","type":"短语","phonetic":"","meaning":"摆脱，除去","example":"We should get rid of the habit of staying up late. / 我们应该改掉熬夜的习惯。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00787","word":"get the best of","type":"短语","phonetic":"","meaning":"胜过","example":"He always tries to get the best of others in an argument. / 在争论中他总是想胜过别人。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00788","word":"get the better of","type":"短语","phonetic":"","meaning":"打败，智胜","example":"Never let fear get the better of you when you try something new. / 尝试新事物时，永远不要让恐惧打败你。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00789","word":"get through","type":"短语","phonetic":"","meaning":"1.通过 2.办完，结束","example":"She worked all night to get through the report. / 她通宵工作以完成这份报告。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00790","word":"get up","type":"短语","phonetic":"","meaning":"1.起床 2.增强，增加","example":"I usually get up at six and run for half an hour. / 我通常六点起床，然后跑半小时步。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00791","word":"gift","type":"名词","phonetic":"/gift/","meaning":"赠品, 礼物, 天赋, 才能","example":"He has a gift for music and plays the piano well. / 他有音乐天赋，钢琴弹得很好。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00792","word":"girl","type":"名词","phonetic":"/ɡə:l/","meaning":"女孩, 少女, 女仆, (商店等的)女工作人员","example":"The little girl gave her seat to an old man on the bus. / 那个小女孩在公交车上把座位让给了一位老人。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00793","word":"give","type":"名词","phonetic":"/giv/","meaning":"弹性, 可弯性 vt. 给, 授予, 供给, 献出,让步, 引起, 发表, 捐助","example":"Please give this note to your parents after school. / 放学后请把这张便条交给你的父母。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00794","word":"give away","type":"短语","phonetic":"","meaning":"1.泄露 2.分送","example":"Do not give away the answer before everyone has tried. / 在大家都尝试过之前不要泄露答案。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00795","word":"give in","type":"短语","phonetic":"","meaning":"1.交上，交来 2.投降，屈服","example":"He refused to give in, even when the work became harder. / 即使工作变得更难，他也拒绝屈服。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00796","word":"give off","type":"短语","phonetic":"","meaning":"放出，释放","example":"The flowers give off a sweet smell in the evening. / 这些花在傍晚散发出甜甜的香味。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00797","word":"give out","type":"短语","phonetic":"","meaning":"分发，放出","example":"Volunteers will give out free books at the school gate. / 志愿者将在校门口免费分发书籍。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00798","word":"give sb. a helping hand","type":"短语","phonetic":"","meaning":"帮助某人","example":"We should give our classmates a helping hand when they are in trouble. / 当同学遇到困难时，我们应该伸出援手。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00799","word":"give up","type":"短语","phonetic":"","meaning":"停止；放弃","example":"Never give up when you meet a difficult problem. / 遇到难题时永远不要放弃。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00800","word":"give way to","type":"短语","phonetic":"","meaning":"让路","example":"Drivers should give way to people who are crossing the road. / 司机应该给正在过马路的人让路。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00801","word":"glad","type":"形容词","phonetic":"/glæd/","meaning":"高兴的, 乐意的, 感到高兴的","example":"I am glad to hear that you passed the exam. / 听说你通过了考试，我很高兴。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00802","word":"glass","type":"名词","phonetic":"/glɑ:s/","meaning":"1.玻璃 2.玻璃杯 3.（pl.）眼镜","example":"He poured a glass of water and drank it quickly. / 他倒了一杯水，很快喝了下去。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00803","word":"go","type":"不及物动词","phonetic":"/gəu/","meaning":"1. 去，走 2. 放置，运行 3. 运转，运行 4. 变为，成为 5. 消失，离去","example":"Many students go to the library after class. / 许多学生下课后去图书馆。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00804","word":"go after","type":"短语","phonetic":"","meaning":"追求","example":"You should go after your dream, even if it is hard. / 即使很难，你也应该去追求自己的梦想。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00805","word":"goal","type":"名词","phonetic":"/gəul/","meaning":"1.目的, 目标 2. 球门 3. (球赛等的)得分","example":"Her goal is to pass the exam and enter a good college. / 她的目标是考试及格并进入一所好大学。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00806","word":"goat","type":"名词","phonetic":"/gəut/","meaning":"山羊","example":"A white goat was eating grass on the hill. / 一只白山羊正在山坡上吃草。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00807","word":"go back on","type":"短语","phonetic":"","meaning":"违背","example":"Please do not go back on your promise to help us. / 请不要违背你帮我们的承诺。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00808","word":"go by","type":"短语","phonetic":"","meaning":"过去","example":"Do not let the chance go by, or you may regret it. / 别让这个机会过去，否则你可能会后悔。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00809","word":"god","type":"名词","phonetic":"/gɔd/","meaning":"上帝","example":"They thanked God for the safe return of the missing child. / 他们为失踪孩子的平安归来感谢上帝。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00810","word":"go down","type":"短语","phonetic":"","meaning":"1.下降，降低 2.被载入，传下去","example":"Prices of vegetables may go down after the harvest. / 蔬菜的价格可能在收获后下降。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00811","word":"go in for","type":"短语","phonetic":"","meaning":"参加","example":"More and more students go in for sports after school. / 越来越多的学生放学后参加体育运动。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00812","word":"gold","type":"名词","phonetic":"/gəuld/","meaning":"黄金, 金币 adj. 金的, 金制的","example":"The ring is made of gold and looks very beautiful. / 这枚戒指是黄金做的，看起来非常漂亮。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00813","word":"golden","type":"形容词","phonetic":"/'gəuldən/","meaning":"金色的, 金黄色的, 贵重的, 极好的,黄金的","example":"The golden leaves on the trees tell us autumn has come. / 树上金黄色的叶子告诉我们秋天来了。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00814","word":"good","type":"形容词","phonetic":"/gud/","meaning":"1.好的 2.（for）适合的，有益的","example":"Reading before bed is good for both mind and sleep. / 睡前阅读对身心和睡眠都有好处。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00815","word":"goodbye","type":"感叹词","phonetic":"/ˌɡʊd'baɪ/","meaning":"再见","example":"She waved her hand and said goodbye to us at the gate. / 她在门口挥手向我们告别。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00816","word":"goods","type":"名词","phonetic":"/gudz/","meaning":"货物, 商品","example":"The goods you ordered will arrive in three days. / 你订的货物将在三天后送到。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00817","word":"go off","type":"短语","phonetic":"","meaning":"1.爆炸，发射 2.动身，离开","example":"They plan to go off to the countryside early tomorrow morning. / 他们打算明天一早动身去乡下。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00818","word":"go on","type":"短语","phonetic":"","meaning":"1.继续 2.发生","example":"Just go on with your work and do not worry about the noise. / 继续做你的事，别担心那些噪音。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00819","word":"goose","type":"名词","phonetic":"/gu:s/","meaning":"鹅","example":"A goose swam across the lake with her little ones. / 一只鹅带着小鹅游过了湖面。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00820","word":"go out","type":"短语","phonetic":"","meaning":"1.外出 2.熄灭","example":"The lights go out at eleven in our dormitory. / 我们宿舍十一点熄灯。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00821","word":"go over","type":"短语","phonetic":"","meaning":"1.检查，审查 2.复习，温习","example":"Let us go over the notes before the test tomorrow. / 明天的考试前我们把笔记复习一遍吧。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00822","word":"go through","type":"短语","phonetic":"","meaning":"1.经历，经受 2.详细检查?","example":"She had to go through many difficulties before she succeeded. / 她在成功之前不得不经历许多困难。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00823","word":"go up","type":"短语","phonetic":"","meaning":"1.上升，增加 2.建起","example":"Many students worry that food prices will go up again. / 许多学生担心食品价格会再次上涨。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00824","word":"government","type":"名词","phonetic":"/'gʌvənmənt/","meaning":"政府，政体","example":"The government has built many new schools in the countryside. / 政府在农村建了许多新学校。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00825","word":"go with","type":"短语","phonetic":"","meaning":"1.伴随 2.与…协调","example":"This white shirt will go with your blue trousers very well. / 这件白衬衫会很配你的蓝裤子。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00826","word":"go without","type":"短语","phonetic":"","meaning":"没有…也行","example":"Some poor families often have to go without meat for a week. / 一些贫困家庭常常不得不一周不吃肉。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00827","word":"go wrong","type":"短语","phonetic":"","meaning":"发生故障，出毛病","example":"Something may go wrong if you do not check the machine. / 如果你不检查机器，可能会出故障。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00828","word":"grade","type":"名词","phonetic":"/greid/","meaning":"等级, 级别 vt. 评分, 评级","example":"My sister got a good grade in the math test last week. / 我妹妹上周的数学考试得了好成绩。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00829","word":"gram(me)","type":"名词","phonetic":"/ɡræm/","meaning":"克","example":"Add fifty grams of sugar to the milk and mix them well. / 往牛奶里加五十克糖并搅拌均匀。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00830","word":"grandfather","type":"名词","phonetic":"/ˌgrænd'fɑ:ðə/","meaning":"（外）祖父","example":"My grandfather often takes a walk in the park after supper. / 我爷爷经常在晚饭后去公园散步。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00831","word":"grandmother","type":"名词","phonetic":"/ˌgrænd'mʌðə/","meaning":"（外）祖母","example":"My grandmother grows vegetables in a small garden behind the house. / 我奶奶在屋后的小园子里种蔬菜。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00832","word":"grass","type":"名词","phonetic":"/grɑ:s/","meaning":"草","example":"The children were sitting on the grass and reading books. / 孩子们坐在草地上看书。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00833","word":"great","type":"形容词","phonetic":"/ɡreɪt/","meaning":"伟大的, 大的; 美好的，绝妙的","example":"We had a great time at the school sports meeting. / 我们在学校运动会上玩得非常开心。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00834","word":"greatly","type":"副词","phonetic":"/'gri:tli/","meaning":"大大地, 非常","example":"The new library has greatly changed the life of our students. / 新图书馆大大改变了我们学生的生活。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00835","word":"green","type":"形容词","phonetic":"/gri:n/","meaning":"1. 绿色的, 青的 2. 未熟的，嫩的 n. 1.绿色 2.(pl.)蔬菜，植物","example":"She painted the walls green and put some flowers in the room. / 她把墙刷成绿色，还在房间里放了些花。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00836","word":"greet","type":"及物动词","phonetic":"/gri:t/","meaning":"问候, 向...致意","example":"Every morning the teacher greets us with a warm smile. / 每天早上老师都微笑着迎接我们。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00837","word":"greeting","type":"名词","phonetic":"/'ɡri:tɪŋ/","meaning":"致意, 问候","example":"He sent me a greeting card for the new year. / 他给我寄了一张新年贺卡。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00838","word":"grey / gray","type":"形容词","phonetic":"","meaning":"灰色的, 灰白的 n. 灰色","example":"The sky turned gray before the heavy rain came. / 大雨来临前天空变成了灰色。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00839","word":"grocery","type":"名词","phonetic":"/'ɡrəʊs(ə)ri/","meaning":"食品杂货（店）","example":"My mother buys fresh vegetables at the grocery near our home. / 我妈妈在我们家附近的杂货店买新鲜蔬菜。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00840","word":"ground","type":"名词","phonetic":"/graund/","meaning":"1. 地，地面 2. 场, 场所 3. 根据，理由","example":"The children sat on the ground and watched the clouds. / 孩子们坐在地上看云。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00841","word":"group","type":"名词","phonetic":"/gru:p/","meaning":"组, 群 vt. 把…分组","example":"Our group finished the science project two days earlier. / 我们小组提前两天完成了科学项目。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00842","word":"grow","type":"不及物动词","phonetic":"/grəu/","meaning":"1. 生长, 成长 2. 渐渐变得 vt. 种植, 栽培","example":"These young trees grow very fast in warm and wet weather. / 这些幼树在温暖潮湿的天气里长得很快。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00843","word":"guard","type":"名词","phonetic":"/gɑ:d/","meaning":"1. 卫兵，警卫员 2. 守卫，看守 vt. 保卫,守卫 vi. (against)防止, 防范","example":"A guard stands at the gate of the museum every day. / 每天都有警卫站在博物馆门口。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00844","word":"guess","type":"及物动词","phonetic":"/ges/","meaning":"猜测, 推测 n. 猜测, 推测","example":"Can you guess how many students joined the club this term? / 你能猜出这学期有多少学生加入了社团吗？","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00845","word":"guest","type":"名词","phonetic":"/gest/","meaning":"客人","example":"Every guest received a small gift at the school gate. / 每位客人在校门口都收到了一份小礼物。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00846","word":"guide","type":"名词","phonetic":"/gaid/","meaning":"领路人, 导游; 指南 vt. 为…领路，指导","example":"The guide told us many interesting stories about the old town. / 导游给我们讲了许多关于这座古镇的有趣故事。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00847","word":"gun","type":"名词","phonetic":"/gʌn/","meaning":"炮, 枪","example":"In the museum we saw an old gun from a hundred years ago. / 在博物馆里我们看到了一把一百年前的旧枪。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00848","word":"habit","type":"名词","phonetic":"/'hæbit/","meaning":"习惯, 习性","example":"Reading before sleep is a good habit for every student. / 睡前阅读是每个学生的好习惯。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00849","word":"had better","type":"短语","phonetic":"","meaning":"最好还是","example":"You had better see a doctor before the fever gets worse. / 你最好在发烧变严重之前去看医生。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00850","word":"hair","type":"名词","phonetic":"/hɛə/","meaning":"头发, 毛发, 毛状物,","example":"She cut her hair short before the new school term began. / 新学期开始前她把头发剪短了。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00851","word":"half","type":"名词","phonetic":"/hɑ:f/","meaning":"一半, 半时, 半学年 adj. 一半的, 不完全的, adv. 一半地, 部分地","example":"Half of the students in our class walk to school every day. / 我们班有一半学生每天步行上学。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00852","word":"hall","type":"名词","phonetic":"/hɔ:l/","meaning":"会堂, 礼堂, 大厅, 走廊, 门厅","example":"The meeting will be held in the hall on the second floor. / 会议将在二楼的大厅举行。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00853","word":"hand","type":"名词","phonetic":"/hænd/","meaning":"手, 协助, 指针; vt.支持, 交给","example":"Please raise your hand if you know the answer. / 知道答案的同学请举手。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00854","word":"hand down","type":"短语","phonetic":"","meaning":"流传下来","example":"Grandparents often hand down old stories to their grandchildren. / 祖父母常把古老的故事传给孙辈。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00855","word":"hand in","type":"短语","phonetic":"","meaning":"递交，交上","example":"Please hand in your homework before Friday afternoon. / 请在周五下午之前交上你的作业。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00856","word":"hand in hand","type":"短语","phonetic":"","meaning":"关系密切地；手拉着手地","example":"Reading and writing go hand in hand in language learning. / 在语言学习中，读和写是密不可分的。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00857","word":"handkerchief","type":"名词","phonetic":"/'hæŋkəʧif/","meaning":"手帕","example":"He took a handkerchief out of his pocket and wiped his face. / 他从口袋里拿出手帕擦了擦脸。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00858","word":"hand out","type":"短语","phonetic":"","meaning":"分发，散发","example":"The volunteers will hand out warm clothes to the children. / 志愿者将给孩子们分发保暖衣物。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00859","word":"hand over","type":"短语","phonetic":"","meaning":"转交， 发出","example":"Please hand over your passport to the officer at the desk. / 请把你的护照交给服务台的官员。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00860","word":"handsome","type":"形容词","phonetic":"/'hænsəm/","meaning":"英俊的, 漂亮的, 慷慨的, 美观的,","example":"Her brother is a tall and handsome young man. / 她哥哥是个又高又英俊的年轻人。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00861","word":"hang","type":"及物动词","phonetic":"/hæŋ/","meaning":"悬挂, 绞死, 垂下 vi. 悬着, 垂下, 被绞死","example":"Please hang your coat on the hook behind the door. / 请把你的外套挂在门后的钩子上。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00862","word":"hang about","type":"短语","phonetic":"","meaning":"闲呆着，终日无所事事","example":"Some boys hang about the square after school with nothing to do. / 一些男孩放学后在广场闲逛，无事可做。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00863","word":"hang back","type":"短语","phonetic":"","meaning":"畏缩不前，退缩","example":"Do not hang back when the teacher asks for volunteers. / 老师招募志愿者时不要退缩。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00864","word":"hang on","type":"短语","phonetic":"","meaning":"紧握着，（电话用语）别挂断，仔细听","example":"Hang on for a moment; the manager is coming to the phone. / 请稍等，经理马上来接电话。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00865","word":"happen to do sth.","type":"短语","phonetic":"","meaning":"碰巧，巧遇","example":"I happen to know the way to the train station. / 我碰巧知道去火车站的路。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00866","word":"happen to sb (sth)","type":"短语","phonetic":"","meaning":"发生（某事件）；对…产生影响","example":"Strange things happen to everyone in a new school. / 在新学校里，奇怪的事情会发生在每个人身上。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00867","word":"happy","type":"形容词","phonetic":"/'hæpi/","meaning":"快乐的, 幸福的, 陶醉于...的, 恰当的","example":"The children were happy to hear the news of the trip. / 孩子们听到旅行的消息很开心。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00868","word":"harbo(u)r","type":"名词","phonetic":"/'hɑ:bə/","meaning":"海港，避难所","example":"Several fishing boats came back to the harbor before dark. / 几艘渔船在天黑前回到了港口。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00869","word":"hard","type":"形容词","phonetic":"/hɑ:d/","meaning":"困难的, 艰苦的 adj. 硬的, 坚固的,dv.努力地, 辛苦地, 坚硬地, 困难地","example":"It is hard to finish so much work in one afternoon. / 在一个下午完成这么多工作很难。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00870","word":"hardly","type":"副词","phonetic":"/'hɑ:dli/","meaning":"几乎不，简直不，绝不","example":"I can hardly hear the teacher because of the noise outside. / 外面的噪音太大，我几乎听不见老师说话。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00871","word":"harvest","type":"名词","phonetic":"/'hɑ:vist/","meaning":"收获, 收成, 成果 v. 收获, 收割","example":"The farmers are busy with the autumn harvest this week. / 农民们这周正忙着秋收。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00872","word":"hat","type":"名词","phonetic":"/hæt/","meaning":"帽子","example":"He put on a hat before going out into the sun. / 他出门晒太阳前戴上了帽子。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00873","word":"hate","type":"及物动词","phonetic":"/heit/","meaning":"憎恨, 恨, 不愿, 不喜欢 n.憎恶, 憎恨","example":"Many students hate getting up early on cold winter mornings. / 许多学生讨厌在寒冷的冬日早晨早起。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00874","word":"have","type":"动词","phonetic":"/hæv/","meaning":"aux. （加过去分词，构成完成时态）已经，曾经 vt. 有, 拿, 从事，经历，使","example":"We have a small garden behind our classroom building. / 我们教室楼后面有一个小花园。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00875","word":"have an influence on","type":"短语","phonetic":"","meaning":"对…产生影响 vt.影响, 改变","example":"Good teachers have an influence on the whole life of a student. / 好老师会影响学生的一生。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00876","word":"have / get some idea of sth.","type":"短语","phonetic":"","meaning":"大概了解","example":"After the visit, we have some idea of how the factory works. / 参观之后，我们对工厂的运作有了大致了解。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00877","word":"have got","type":"短语","phonetic":"","meaning":"有","example":"I have got two brothers and one little sister. / 我有两个兄弟和一个小妹妹。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00878","word":"have no idea","type":"短语","phonetic":"","meaning":"不知道","example":"I have no idea when the meeting will start. / 我不知道会议什么时候开始。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00879","word":"have no intention of doing sth.","type":"短语","phonetic":"","meaning":"没…的意图","example":"They have no intention of moving to another city. / 他们没有搬到另一个城市的打算。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00880","word":"have nothing to do with","type":"短语","phonetic":"","meaning":"和…毫无关系","example":"These two problems have nothing to do with each other. / 这两个问题彼此毫无关系。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00881","word":"have something done","type":"短语","phonetic":"","meaning":"叫别人做某事","example":"You should have your eyes checked once a year. / 你应该每年请人检查一次眼睛。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00882","word":"have something to do with","type":"短语","phonetic":"","meaning":"和…有点关系","example":"His success may have something to do with his daily reading habit. / 他的成功可能和他每天阅读的习惯有点关系。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00883","word":"have sth. in mind","type":"短语","phonetic":"","meaning":"1. 记住 2. 考虑到，想到","example":"Please have these safety rules in mind when you travel. / 旅行时请把这些安全规则记在心里。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00884","word":"have to","type":"短语","phonetic":"","meaning":"不得不，必须","example":"Students have to wear school uniforms on Monday mornings. / 学生星期一早上必须穿校服。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00885","word":"he","type":"代词","phonetic":"/hi:/","meaning":"他","example":"He plays basketball with his friends every Saturday afternoon. / 他每周六下午和朋友们打篮球。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00886","word":"head","type":"名词","phonetic":"/hed/","meaning":"头, 头脑，首脑, 领袖 ；vt.朝向, 率领, 用头顶","example":"She turned her head and smiled at the little girl. / 她转过头，对小女孩笑了笑。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00887","word":"headache","type":"名词","phonetic":"/'hedeik/","meaning":"头痛, 令人头痛之事","example":"Too much screen time often gives me a bad headache. / 看屏幕太久常常让我头痛得厉害。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00888","word":"head for","type":"短语","phonetic":"","meaning":"向…走去","example":"After class, the students head for the dining hall quickly. / 下课后学生们快步走向食堂。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00889","word":"health","type":"名词","phonetic":"/helθ/","meaning":"健康, 健康状况","example":"Enough sleep is important for the health of young people. / 充足的睡眠对年轻人的健康很重要。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00890","word":"healthy","type":"形容词","phonetic":"/'helθi/","meaning":"健康的, 健壮的, 有益于健康的","example":"Eating more vegetables keeps us healthy and full of energy. / 多吃蔬菜能让我们保持健康、精力充沛。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00891","word":"hear","type":"及物动词","phonetic":"/hiə/","meaning":"听到, 听说, 听取,vi. 听见, 听到","example":"I can hear birds singing outside my window every morning. / 我每天早上都能听见窗外鸟儿在唱歌。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00892","word":"heart","type":"名词","phonetic":"/hɑ:t/","meaning":"心, 心脏, 中心; vt. 把...放在中心","example":"Running every day is very good for your heart. / 每天跑步对你的心脏很有好处。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00893","word":"heat","type":"名词","phonetic":"/hi:t/","meaning":"热, 热度, 温度 vi. 加热, 发热, 发怒 vt.把...加热, 使激动","example":"The heat of the sun made the workers very tired. / 太阳的热量让工人们非常疲惫。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00894","word":"heaven","type":"名词","phonetic":"/'hevn/","meaning":"天, 天空, 天堂","example":"For a book lover, a quiet library is heaven. / 对爱读书的人来说，安静的图书馆就是天堂。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00895","word":"heavy","type":"形容词","phonetic":"/'hevi/","meaning":"1. 重的, 沉重的, 猛烈的 2. 大的；大量的；过量的 adv. 沉重地, 笨重地, 大量地","example":"The box was too heavy for the little boy to carry. / 这个箱子太重了，小男孩搬不动。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00896","word":"height","type":"名词","phonetic":"/hait/","meaning":"高，高度, 海拔, 高地(常用复数)","example":"The height of the mountain makes climbing very difficult. / 这座山的高度使攀登非常困难。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00897","word":"hello","type":"感叹词","phonetic":"/ˌhə'ləu/","meaning":"（招呼语）喂, 哈罗","example":"She said hello to everyone when she came into the room. / 她进屋时向每个人问好。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00898","word":"help","type":"名词","phonetic":"/help/","meaning":"帮忙, 援助, 助手 v. 帮助, 助长, 有用","example":"Thank you for your help with my English writing. / 谢谢你帮我提高英语写作。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00899","word":"help oneself to sth.","type":"短语","phonetic":"","meaning":"自助，（进餐时）自己取用 can’t help doing sth. 禁不住做某事","example":"Please help yourself to some fruit and tea. / 请随便吃点水果、喝点茶。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00900","word":"help out","type":"短语","phonetic":"","meaning":"救助，协助（渡过难关）","example":"Many students help out at the old people's home on Sundays. / 许多学生周日在养老院帮忙。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00901","word":"help sb. with sth.","type":"短语","phonetic":"","meaning":"帮助某人做某事","example":"I often help my sister with her math homework. / 我经常帮助妹妹做数学作业。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00902","word":"her","type":"代词","phonetic":"/hə:/","meaning":"(she 的宾格)她，（she 的所有格）她的,","example":"Her English is much better than it was last year. / 她的英语比去年好多了。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00903","word":"here","type":"副词","phonetic":"/hiə/","meaning":"这里，在这里; n. 这里","example":"Please put your bags here and wait for the bus. / 请把你的包放在这里，然后等公交车。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00904","word":"hero","type":"名词","phonetic":"/'hiərəu/","meaning":"英雄, 男主角, 男主人公","example":"The young doctor became a hero in the eyes of the villagers. / 那位年轻医生成了村民们眼中的英雄。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00905","word":"hers","type":"代词","phonetic":"/hə:z/","meaning":"她的（she 的物主代词）","example":"This blue umbrella is hers, and the red one is mine. / 这把蓝伞是她的，红的那把是我的。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00906","word":"herself","type":"代词","phonetic":"/hɜ:'sɛlf/","meaning":"她自己, 她本人","example":"She made the birthday cake herself last night. / 昨晚她自己做了生日蛋糕。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00907","word":"hi","type":"感叹词","phonetic":"/haɪ/","meaning":"嗨!(引人注意时的喊声,打招呼)","example":"Hi, Lily! How was your weekend in the countryside? / 嗨，莉莉！你在乡下的周末过得怎么样？","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00908","word":"hide","type":"动词","phonetic":"/haid/","meaning":"隐藏, 掩藏, 隐瞒, 掩饰","example":"The little cat likes to hide under the bed when it is afraid. / 小猫害怕时喜欢躲在床底下。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00909","word":"high","type":"形容词","phonetic":"/hai/","meaning":"高的, 高等的, 高尚的, 严重的 adv.高度地, 高价地","example":"The wall is too high for the children to climb over. / 这堵墙太高了，孩子们爬不过去。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00910","word":"hill","type":"名词","phonetic":"/hil/","meaning":"小山, 丘陵, 斜坡, 山岗","example":"We walked up the hill to watch the sunrise. / 我们爬上小山去看日出。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00911","word":"him","type":"代词","phonetic":"/him/","meaning":"他（he 的宾格）","example":"I met him at the school gate this morning. / 今天早上我在校门口遇见了他。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00912","word":"himself","type":"代词","phonetic":"/hɪm'sɛlf/","meaning":"他自己, 他亲自,他本人","example":"He fixed the broken chair himself without any help. / 他自己一个人修好了那把坏椅子。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00913","word":"his","type":"代词","phonetic":"/hiz/","meaning":"他的（he 的所有格）","example":"His new bike is parked in front of the library. / 他的新自行车停在图书馆门前。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00914","word":"history","type":"名词","phonetic":"/'histəri/","meaning":"历史, 历史学, 历史记录","example":"History teaches us how people lived in the past. / 历史教我们了解过去的人是怎样生活的。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00915","word":"hit","type":"名词","phonetic":"/hit/","meaning":"打击, 打, 碰撞; v.打, 打击, 碰撞, 击中","example":"He felt a light hit on his shoulder and turned around. / 他感觉肩膀被轻轻打了一下，就转过身来。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00916","word":"hit it off","type":"短语","phonetic":"","meaning":"相处得好；合得来","example":"The two new classmates hit it off on the first day. / 这两位新同学第一天就相处得很好。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00917","word":"hoe","type":"名词","phonetic":"/həʊ/","meaning":"锄头; v.用锄耕地, 锄","example":"The old farmer worked in the field with a hoe. / 那位老农拿着锄头在地里干活。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00918","word":"hold","type":"名词","phonetic":"/həuld/","meaning":"把握, 控制, 掌握 vt.1.拿着, 支持, 占据, 持有 2. 屏住 vi.支持, 保持, 有效","example":"He kept a firm hold on the rope and climbed up. / 他紧紧抓住绳子往上爬。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00919","word":"hold back","type":"短语","phonetic":"","meaning":"阻止，退缩","example":"She could not hold back her tears when she heard the news. / 听到这个消息，她忍不住流下了眼泪。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00920","word":"hold on","type":"短语","phonetic":"","meaning":"（打电话时用语）请等一下, 不要挂","example":"Hold on a minute; I will write down your number. / 请稍等一下，我把你的号码记下来。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00921","word":"hold out","type":"短语","phonetic":"","meaning":"提供，支持；继续","example":"The team decided to hold out until help arrived. / 队伍决定坚持到救援到来。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00922","word":"hold to","type":"短语","phonetic":"","meaning":"坚持；遵循","example":"We should hold to our plan even when it is difficult. / 即使困难，我们也应该坚持我们的计划。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00923","word":"hold up","type":"短语","phonetic":"","meaning":"使停滞，举起","example":"Heavy snow may hold up the train for several hours. / 大雪可能会使火车延误几个小时。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00924","word":"hole","type":"名词","phonetic":"/həul/","meaning":"洞, 孔, 突破口","example":"There is a small hole in the wall of the classroom. / 教室的墙上有一个小洞。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00925","word":"holiday","type":"名词","phonetic":"/'hɔlədi/","meaning":"假日, 节日, 假期","example":"We spent the summer holiday helping on my uncle's farm. / 我们暑假在我叔叔的农场帮忙。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00926","word":"home","type":"名词","phonetic":"/həum/","meaning":"家, 家乡, 本国 adj.家庭的, 国内的, 有效的 adv.在家, 回家, 在本国","example":"She goes home by bike every afternoon after class. / 她每天下午放学后骑自行车回家。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00927","word":"homework","type":"名词","phonetic":"/'həumwə:k/","meaning":"家庭作业, 副业，准备工作","example":"I finish my homework before dinner every evening. / 我每天晚上在晚饭前完成作业。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00928","word":"honest","type":"形容词","phonetic":"/'ɔnist/","meaning":"诚实的, 正直的","example":"An honest person always tells the truth, even when it is hard. / 诚实的人总是说真话，即使这很难。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00929","word":"hono(u)r","type":"名词","phonetic":"/'ɒnə/","meaning":"尊敬, 敬意, 荣誉 vt.尊敬, 给以荣誉","example":"It is a great honor to meet your family today. / 今天能见到你的家人是我的荣幸。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00930","word":"hono(u)rable","type":"形容词","phonetic":"/'ɒnərəbl/","meaning":"可敬的, 荣誉的, 光荣的","example":"Returning the lost wallet was an honorable thing to do. / 把丢失的钱包还回去是一件值得尊敬的事。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00931","word":"hope","type":"名词","phonetic":"/həup/","meaning":"希望, 信心 v.希望, 盼望, 期待","example":"There is still hope that the weather will turn fine. / 天气还有转晴的希望。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00932","word":"horse","type":"名词","phonetic":"/hɔ:s/","meaning":"马","example":"A horse was eating grass quietly by the river. / 一匹马在河边安静地吃草。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00933","word":"hospital","type":"名词","phonetic":"/'hɔspitl/","meaning":"医院","example":"My aunt works as a nurse in the city hospital. / 我姑姑在市医院当护士。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00934","word":"host","type":"名词","phonetic":"/həust/","meaning":"主人, 节目主持人","example":"The host of the party welcomed every guest at the door. / 聚会的东道主在门口迎接每位客人。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00935","word":"hot","type":"形容词","phonetic":"/hɔt/","meaning":"热的, 热情的, 辣的, 激动的; adv.热切的,紧迫地","example":"It is very hot in the classroom without a fan. / 没有风扇的教室里非常热。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00936","word":"hotel","type":"名词","phonetic":"/həu'tel/","meaning":"旅馆, 客栈","example":"We stayed in a small hotel near the beach last summer. / 去年夏天我们住在海滩附近的一家小旅馆。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00937","word":"hour","type":"名词","phonetic":"/'auə/","meaning":"小时, 钟头, (一段)时间","example":"The train ride to the next town takes about an hour. / 到下一个镇的火车大约要一个小时。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00938","word":"house","type":"名词","phonetic":"/haus/","meaning":"房子, 住宅, 机构；vt.给房子住","example":"Their house has a small garden full of flowers. / 他们的房子有一个开满鲜花的小花园。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00939","word":"housewife","type":"名词","phonetic":"/'hauswaif/","meaning":"家庭主妇, 针线盒","example":"Her mother is a housewife and takes good care of the family. / 她妈妈是家庭主妇，把家照顾得很好。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00940","word":"housework","type":"名词","phonetic":"/'hauswə:k/","meaning":"家务劳动, 家务事","example":"Every child in our family shares some housework after dinner. / 我们家每个孩子晚饭后都分担一些家务。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00941","word":"how","type":"副词","phonetic":"/hau/","meaning":"（指范围, 程度, 数量, 价值）多少, 多么","example":"How do you go to school every day? / 你每天怎么去上学？","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00942","word":"How about","type":"短语","phonetic":"","meaning":"怎么样","example":"How about going swimming this Saturday afternoon? / 这个周六下午去游泳怎么样？","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00943","word":"however","type":"副词","phonetic":"/hau'evə/","meaning":"无论如何, 不管怎样，可是 conj.不管用什么方法, 然而","example":"The weather was cold; however, the students finished the run. / 天气很冷，然而学生们还是跑完了。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00944","word":"huge","type":"形容词","phonetic":"/hju:ʤ/","meaning":"巨大的, 极大的, 无限的","example":"A huge crowd waited outside the concert hall. / 一大群人在音乐厅外等候。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00945","word":"human","type":"名词","phonetic":"/'hju:mən/","meaning":"人, 人类；adj.人的, 人类的, 人性的","example":"A human cannot live without water for more than a few days. / 人没有水活不过几天。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00946","word":"humo(u)r","type":"名词","phonetic":"/hju:mə(r)/","meaning":".幽默, 诙谐","example":"His humor makes every class interesting and lively. / 他的幽默让每节课都有趣又活跃。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00947","word":"hundred","type":"名词","phonetic":"/'hʌndrid/","meaning":"一百个, 许多; num.百, 百个","example":"More than a hundred students joined the tree planting activity. / 一百多名学生参加了植树活动。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00948","word":"hunger","type":"名词","phonetic":"/'hʌŋɡə/","meaning":"饥饿, 欲望 v.饥饿, 渴望","example":"After the long walk up the hill, they felt real hunger. / 爬上山坡后，他们真的感到饿了。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00949","word":"hurry","type":"动词","phonetic":"/'hʌri/","meaning":"(使)赶紧, (使)匆忙, 加速 n.匆忙, 仓促","example":"Do not hurry; we still have plenty of time. / 别着急，我们还有很多时间。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00950","word":"hurt","type":"动词","phonetic":"/hə:t/","meaning":"刺痛, 伤害, (使)痛心 n.伤痛, 伤害","example":"My leg still hurts when I run for a long time. / 我跑很久的时候腿还会疼。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00951","word":"husband","type":"名词","phonetic":"/'hʌzbənd/","meaning":"丈夫","example":"Her husband cooks dinner for the family every Sunday. / 她丈夫每个周日为家人做晚饭。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00952","word":"I","type":"代词","phonetic":"/ai/","meaning":"我","example":"I usually read English stories before going to bed. / 我通常在睡觉前读英语故事。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00953","word":"ice","type":"名词","phonetic":"/ais/","meaning":"冰，冰块，冰冻食品; v.冰冻, 结冰","example":"The children put some ice in their drinks on the hot day. / 天气很热，孩子们在饮料里放了些冰。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00954","word":"idea","type":"名词","phonetic":"/ai'diə/","meaning":"思想, 观念, 想法, 主意, 概念","example":"Your idea about the class party sounds really interesting. / 你关于班级聚会的想法听起来很有意思。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00955","word":"if","type":"连词","phonetic":"/if/","meaning":"如果, 即是, 是否 n.条件, 设想","example":"If you work hard, you will make great progress this term. / 如果你努力学习，这学期你会取得很大进步。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00956","word":"ill","type":"形容词","phonetic":"/il/","meaning":"有病的, 坏的, 恶意的","example":"He stayed at home because he was ill last week. / 他上周病了，所以待在家里。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00957","word":"illness","type":"名词","phonetic":"/'ilnis/","meaning":"疾病, 生病","example":"A long illness kept her away from school for a month. / 一场久病让她一个月没能上学。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00958","word":"imagine","type":"及物动词","phonetic":"/i'mæʤin/","meaning":"想像, 设想","example":"Can you imagine life without a mobile phone today? / 你能想象今天没有手机的生活吗？","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00959","word":"immediate","type":"形容词","phonetic":"/i'mi:djət/","meaning":"直接的, 紧靠的, 立即的","example":"The medicine had an immediate effect on his cough. / 这药对他的咳嗽立刻起了作用。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00960","word":"importance","type":"名词","phonetic":"/im'pɔ:təns/","meaning":"重要(性), 重大","example":"Nowadays, an increasing number of people come to realize the importance of a good sleep. / 如今，越来越多的人开始意识到良好睡眠的重要性。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00961","word":"important","type":"形容词","phonetic":"/im'pɔ:tənt/","meaning":"重要的, 重大的, 有权力的, 有地位的","example":"It is important for us to keep the classroom clean and tidy. / 对我们来说，保持教室干净整洁很重要。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00962","word":"impossible","type":"形容词","phonetic":"/im'pɔsəbl/","meaning":"不可能的, 办不到的","example":"It is impossible to finish so much work within one hour. / 在一小时内完成这么多工作是不可能的。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00963","word":"in","type":"介词","phonetic":"/in/","meaning":"在...之内, 在...期间, 在...方面 adv.进入, 向内, 在家, 到达 adj.在里面的, 执政的","example":"Many students read English stories in the school library every day. / 许多学生每天在学校图书馆读英语故事。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00964","word":"in all","type":"短语","phonetic":"","meaning":"总共","example":"The whole trip took five days in all. / 整个旅行总共花了五天。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00965","word":"in a moment","type":"短语","phonetic":"","meaning":"立刻，马上","example":"The taxi will be here in a moment, so please wait outside. / 出租车马上就到，请在外面稍等。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00966","word":"in any case","type":"短语","phonetic":"","meaning":"无论如何","example":"In any case, you must hand in the report before Friday. / 无论如何，你必须在周五前交上报告。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00967","word":"in a word","type":"短语","phonetic":"","meaning":"简言之，一句话，总之","example":"In a word, we should save water in our daily life. / 总之，我们应该在日常生活中节约用水。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00968","word":"in brief","type":"短语","phonetic":"","meaning":"简单地说，简言之","example":"In brief, the meeting was short but very useful. / 简言之，这次会议很短但很有用。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00969","word":"in case","type":"短语","phonetic":"","meaning":"万一","example":"Take an umbrella with you in case it rains this afternoon. / 带把伞，万一今天下午下雨呢。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00970","word":"in case of","type":"短语","phonetic":"","meaning":"如果；万一","example":"In case of fire, please leave the building by the back door. / 万一发生火灾，请从后门离开大楼。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00971","word":"inch","type":"名词","phonetic":"/inʧ/","meaning":"英寸(=1/12 英尺)","example":"This small box is only one inch wide, so it fits the pocket. / 这个小盒子只有一英寸宽，正好放进口袋。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00972","word":"in charge of","type":"短语","phonetic":"","meaning":"负责","example":"Miss Li is in charge of the school music club. / 李老师负责学校的音乐社团。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00973","word":"income","type":"名词","phonetic":"/'inkʌm/","meaning":"收入, 收益, 所得","example":"His income has grown since he changed to a better job. / 自从换了一份更好的工作，他的收入增加了。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00974","word":"in consequence of","type":"短语","phonetic":"","meaning":"由于…缘故","example":"In consequence of the heavy snow, all the classes were put off. / 由于大雪的缘故，所有课程都被推迟了。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00975","word":"increase","type":"名词","phonetic":"/in'kri:s/","meaning":"增加, 增大, 增长 v.增加, 加大","example":"The increase in bus fares has brought trouble to many students. / 公交车票价的上涨给许多学生带来了麻烦。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00976","word":"indeed","type":"副词","phonetic":"/in'di:d/","meaning":"真正地, (加强语气)确实","example":"The old bridge is indeed a beautiful place to take photos. / 这座老桥确实是个拍照的好地方。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00977","word":"in detail","type":"短语","phonetic":"","meaning":"详细地","example":"The teacher explained the grammar rules in detail after class. / 老师下课后详细讲解了这些语法规则。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00978","word":"indoors","type":"副词","phonetic":"/ɪn'dɔ:z/","meaning":"在户内","example":"Because of the strong wind, the children stayed indoors all afternoon. / 由于大风，孩子们整个下午都待在室内。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00979","word":"industry","type":"名词","phonetic":"/'indəstri/","meaning":"工业, 产业, 勤奋","example":"The tourism industry has brought many jobs to this small town. / 旅游业给这个小镇带来了许多工作岗位。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00980","word":"in fact","type":"短语","phonetic":"","meaning":"其实，实际上","example":"In fact, the hardest part of the work is the beginning. / 事实上，这项工作最难的部分是开头。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00981","word":"in favor of","type":"短语","phonetic":"","meaning":"1. 有利于, 便于 2 赞成，支持","example":"Most parents are in favor of the new rule about homework. / 大多数家长赞成关于作业的新规定。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00982","word":"in force","type":"短语","phonetic":"","meaning":"有效，实施中","example":"The new traffic rule will be in force from next month. / 新的交通规则将从下个月起生效。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00983","word":"information","type":"名词","phonetic":"/ˌinfə'meiʃən/","meaning":"通知, 报告, 消息, 情报, 资料，信息","example":"You can get much useful information about the course on its website. / 你可以在课程网站上得到许多有用的信息。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00984","word":"inform sb. of / about sth.","type":"短语","phonetic":"","meaning":"通知, 告诉","example":"Please inform me of any change in the meeting time. / 会议时间如有变动，请通知我。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00985","word":"in general","type":"短语","phonetic":"","meaning":"通常，大体上","example":"In general, young people in the city like to shop online. / 一般来说，城里的年轻人喜欢网上购物。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00986","word":"in hand","type":"短语","phonetic":"","meaning":"在进行中，待办理","example":"The repairs to the playground are in hand and will end soon. / 操场的维修正在进行中，很快就会结束。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00987","word":"in high spirits","type":"短语","phonetic":"","meaning":"非常兴奋","example":"The students were in high spirits after winning the singing contest. / 赢得歌唱比赛后，学生们情绪高涨。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00988","word":"in honour of","type":"短语","phonetic":"","meaning":"纪念，向…表示敬意","example":"A concert was held in honour of the old headmaster. / 人们举办了一场音乐会来纪念这位老校长。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00989","word":"in itself","type":"短语","phonetic":"","meaning":"本身；实质上","example":"The question is not hard in itself, but the time is too short. / 这个问题本身并不难，只是时间太短了。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00990","word":"ink","type":"名词","phonetic":"/iŋk/","meaning":"墨水","example":"The pen is out of ink, so I need to buy a new one. / 这支笔没墨水了，我得买一支新的。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-00991","word":"in line with","type":"短语","phonetic":"","meaning":"和…成直线，和…一致","example":"Our plan should be in line with the needs of the students. / 我们的计划应该符合学生的需要。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00992","word":"in nature","type":"短语","phonetic":"","meaning":"实际上, 本质上","example":"The problem is personal in nature, so we should talk about it quietly. / 这个问题本质上是个人问题，所以我们应该私下安静地谈。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00993","word":"in no case","type":"短语","phonetic":"","meaning":"决不","example":"In no case should we copy others' homework. / 我们决不应当抄袭别人的作业。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00994","word":"in no way","type":"短语","phonetic":"","meaning":"决不","example":"In no way can money take the place of health. / 金钱决不能代替健康。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00995","word":"in other words","type":"短语","phonetic":"","meaning":"换句话说","example":"In other words, hard work is more useful than good luck. / 换句话说，努力比好运更有用。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00996","word":"inquire / enquire","type":"动词","phonetic":"","meaning":"1.（常与 of, about 连用）问；询问 2. （常与 into 连用）调查， 查究","example":"He went to the office to inquire about the exam results. / 他去办公室询问考试结果。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00997","word":"in reply to","type":"短语","phonetic":"","meaning":"回答，答复","example":"In reply to your letter, I am glad to share my holiday plan. / 回复你的来信，我很高兴分享我的假期计划。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00998","word":"in short","type":"短语","phonetic":"","meaning":"简言之，总之","example":"In short, the plan is good, but we need more time. / 总之，这个计划不错，但我们需要更多时间。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-00999","word":"inside","type":"名词","phonetic":"/in'said/","meaning":"里面, 内部; adj.内部的, 秘密的; adv.在里面, 在内部 prep.在…之内","example":"The inside of the old house was cool and quiet in summer. / 这座老房子的里面夏天又凉又安静。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01000","word":"in spite of","type":"短语","phonetic":"","meaning":"不顾，不管(介词短语)","example":"In spite of the rain, the match went on as planned. / 尽管下着雨，比赛还是按计划进行。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01001","word":"instal(l)","type":"及物动词","phonetic":"/in'stɔ:l/","meaning":"安装, 安置, 使就职","example":"Workers came to install a new air conditioner in our classroom. / 工人们来我们教室安装了一台新空调。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01002","word":"instead of","type":"短语","phonetic":"","meaning":"代替; 而不是","example":"She walked to school instead of taking the crowded bus. / 她步行去学校，而不是坐拥挤的公交车。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01003","word":"intend sb./sth. to do sth.","type":"短语","phonetic":"","meaning":"想让…做","example":"We intend him to lead the group discussion tomorrow. / 我们想让他明天主持小组讨论。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01004","word":"international","type":"形容词","phonetic":"/ˌintə'næʃənl/","meaning":"国际的, 世界的","example":"An international film festival will open in our city next week. / 一个国际电影节下周将在我们城市开幕。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01005","word":"internet","type":"名词","phonetic":"/'ɪntənɛt/","meaning":"因特网，互联网","example":"The internet makes it easy for us to talk with friends far away. / 互联网让我们很容易与远方的朋友交谈。","folder":"专升本词汇","level":"专升本","tags":["专升本","专升本高频"]},{"_id":"builtin-en-zsb-01006","word":"in the distance","type":"短语","phonetic":"","meaning":"在远处","example":"We could see a small village in the distance through the window. / 透过窗户，我们能看到远处的一个小村庄。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01007","word":"in (the) future","type":"短语","phonetic":"","meaning":"今后, 将来","example":"In the future, more people may work from home. / 将来，可能会有更多人在家工作。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01008","word":"in the way of","type":"短语","phonetic":"","meaning":"妨碍","example":"Nothing should stand in the way of a child's education. / 任何东西都不应妨碍孩子的教育。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01009","word":"into","type":"介词","phonetic":"/'intu/","meaning":"到...里, 进入到...之内","example":"The boy jumped into the river to swim with his friends. / 男孩跳进河里和朋友们一起游泳。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01010","word":"introduce","type":"及物动词","phonetic":"/ˌintrə'dju:s/","meaning":"介绍, 传入, 引进, 提出","example":"Let me introduce my new roommate to the whole class. / 让我把我的新室友介绍给全班同学。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01011","word":"in vain","type":"短语","phonetic":"","meaning":"徒然，枉然","example":"They tried to open the old door in vain and had to wait. / 他们徒劳地想打开那扇旧门，只好等着。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01012","word":"invite","type":"及物动词","phonetic":"/in'vait/","meaning":"1.邀请，招待 2.引起","example":"Lily invited her classmates to her birthday party on Sunday. / 莉莉邀请同学们参加她周日的生日聚会。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01013","word":"iron","type":"名词","phonetic":"/'aiən/","meaning":"铁, 熨斗, 烙铁; v.烫（衣服）","example":"The hotel room has an iron, so you can press your shirt. / 酒店房间里有熨斗，你可以熨衬衫。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01014","word":"is","type":"动词","phonetic":"/iz/","meaning":"是（be 的第三人称单数现在式）","example":"My father is a bus driver and he loves his job. / 我父亲是一名公交车司机，他很喜欢自己的工作。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01015","word":"island","type":"名词","phonetic":"/'ailənd/","meaning":"岛, 岛屿","example":"A small island lies in the middle of the blue sea. / 蓝色大海的中央有一座小岛。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01016","word":"it","type":"代词","phonetic":"/it/","meaning":"它","example":"It is never too late to learn something new. / 学新东西永远不嫌晚。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01017","word":"it goes without saying","type":"短语","phonetic":"","meaning":"毫无疑问，显然","example":"It goes without saying that health is more important than money. / 毫无疑问，健康比金钱更重要。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01018","word":"its","type":"代词","phonetic":"/its/","meaning":"它的","example":"The city is famous for its quiet streets and old gardens. / 这座城市以安静的街道和老花园而闻名。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01019","word":"itself","type":"代词","phonetic":"/it'self/","meaning":"它本身, 它自己","example":"The old wall itself is a piece of history for the town. / 这堵老墙本身就是这座小镇的一段历史。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01020","word":"jacket","type":"名词","phonetic":"/'ʤækit/","meaning":"短上衣, 夹克","example":"He put on a warm jacket before going out in the wind. / 刮风天出门前他穿上了一件暖和的夹克。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01021","word":"jam","type":"名词","phonetic":"/ʤæm/","meaning":"1 果酱 2 拥挤, 堵塞 v．使卡住， 使塞满","example":"We were caught in a traffic jam and arrived late. / 我们遇上了交通堵塞，到得很晚。","folder":"专升本词汇","level":"专升本","tags":["专升本","专升本高频"]},{"_id":"builtin-en-zsb-01022","word":"January","type":"名词","phonetic":"/'ʤænjuəri/","meaning":"一月（缩写 Jan.）","example":"The new term begins in January and ends in early April. / 新学期一月开始，四月初结束。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01023","word":"job","type":"名词","phonetic":"/ʤɔb/","meaning":"1. 职业，职位 2. 工作，活儿","example":"She found a part-time job in a bookshop near the school. / 她在学校附近的一家书店找到了一份兼职工作。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01024","word":"join","type":"动词","phonetic":"/ʤɔin/","meaning":"1. 参加, 加入 2. 连接, 结合","example":"More than twenty students joined the school chorus this term. / 本学期有二十多名学生加入了学校合唱团。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01025","word":"joke","type":"名词","phonetic":"/ʤəuk/","meaning":"笑话, 玩笑 v. (和...)开玩笑","example":"Grandpa told a joke about a clever cat, and we all smiled. / 爷爷讲了一个关于聪明猫的笑话，我们都笑了。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01026","word":"joy","type":"名词","phonetic":"/ʤɔi/","meaning":"1. 欢乐, 喜悦 2. 乐事，乐趣","example":"The good news brought great joy to the whole family. / 这个好消息给全家带来了极大的喜悦。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01027","word":"judge","type":"名词","phonetic":"/ʤʌʤ/","meaning":"1. 法官, 审判员 2. 裁判员, 评判人, 鉴定人 vt.1. 审理，判定 2. 评定，裁判 3. 断定，判断","example":"The judge listened to both sides before giving his decision. / 法官在作出判决前听取了双方的意见。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01028","word":"judg(e)ment","type":"名词","phonetic":"/'ʤʌʤmənt/","meaning":"1. 审判, 判决 2. 判断力 3. 意见,看法","example":"We should not form a judgment about a person too quickly. / 我们不应该太快对一个人下判断。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01029","word":"juice","type":"名词","phonetic":"/ʤu:s/","meaning":"(水果)汁, 液","example":"A glass of orange juice is a healthy way to start the day. / 一杯橙汁是开始一天的健康方式。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01030","word":"July","type":"名词","phonetic":"/ʤu(:)'lai/","meaning":"七月","example":"They plan to visit the science museum in July. / 他们计划七月去参观科学博物馆。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01031","word":"jump","type":"名词・不及物动词","phonetic":"/ʤʌmp/","meaning":"1. 跳跃, 跳.2. 跳跃, 暴涨","example":"The little girl jumped over the small stone and smiled. / 小女孩跳过那块小石头，笑了。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01032","word":"June","type":"名词","phonetic":"/ʤu:n/","meaning":"六月（缩写 Jun.）","example":"The summer holiday usually starts in June in this city. / 在这座城市，暑假通常六月开始。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01033","word":"just","type":"形容词","phonetic":"/ʤʌst/","meaning":"1. 公正的, 公平的 2. 恰当的, 应得的 adv. 1. 正好, 恰好 2. 仅仅, 只是 3. 刚才","example":"She has just finished her homework and gone out to play. / 她刚做完作业，出去玩了。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01034","word":"justice","type":"名词","phonetic":"/ˈdʒʌstɪs/","meaning":"公平, 公平","example":"A good law should bring justice to every ordinary person. / 好的法律应当给每个普通人带来公平。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01035","word":"keep … from …","type":"短语","phonetic":"","meaning":"防止，预防","example":"Warm clothes can keep you from catching a cold in winter. / 暖和的衣服能让你在冬天不感冒。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01036","word":"keep on","type":"短语","phonetic":"","meaning":"继续不断","example":"If you keep on practising, your spoken English will improve. / 如果你继续练习，你的英语口语会提高。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01037","word":"keep one’s head","type":"短语","phonetic":"","meaning":"保持镇静","example":"It is not easy to keep one's head when everyone around is shouting. / 当周围所有人都在大喊时，保持镇静并不容易。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01038","word":"keep to","type":"短语","phonetic":"","meaning":"坚持，保持","example":"We must keep to the rules of the reading room. / 我们必须遵守阅览室的规定。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01039","word":"keep up","type":"短语","phonetic":"","meaning":"1. 保持 2. 继续进行","example":"Please keep up the good work and never give up. / 请继续保持这样的好表现，永不放弃。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01040","word":"keep up with","type":"短语","phonetic":"","meaning":"向…看齐，赶","example":"Old people sometimes find it hard to keep up with new technology. / 老年人有时觉得很难跟上新技术。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01041","word":"key","type":"名词","phonetic":"/ki:/","meaning":"1. 钥匙 2. 关键 3. (打字机等的)键 4.（to）答案","example":"He lost the key to his office and waited outside. / 他丢了办公室的钥匙，只好在外面等。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01042","word":"kick","type":"动词・名词","phonetic":"/kik/","meaning":"踢","example":"The boy kicked the ball hard and scored a goal. / 男孩用力踢球，进了一球。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01043","word":"kill","type":"动词","phonetic":"/kil/","meaning":"1. 杀死 2. 毁掉","example":"The sudden cold weather killed most of the young plants. / 突然的寒冷天气冻死了大部分幼苗。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01044","word":"kilometer/-tre","type":"名词","phonetic":"/kɪ'lɒmɪtə/","meaning":"\\[物\\]千米, 公里","example":"The school is only one kilometer away from my home. / 学校离我家只有一公里远。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01045","word":"kind","type":"名词","phonetic":"/kaind/","meaning":"种类 adj.仁慈的, 亲切的","example":"What kind of music do you like to listen to after class? / 你课后喜欢听哪种音乐？","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01046","word":"king","type":"名词","phonetic":"/kiŋ/","meaning":"国王","example":"The old king built a stone bridge for the poor villagers. / 老国王为贫穷的村民建了一座石桥。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01047","word":"kiss","type":"名词・动词","phonetic":"/kis/","meaning":"吻","example":"The mother gave her baby a gentle kiss on the face. / 母亲在宝宝脸上轻轻亲了一下。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01048","word":"kitchen","type":"名词","phonetic":"/'kiʧin/","meaning":"厨房","example":"My mother is cooking noodles in the small kitchen. / 我妈妈正在小厨房里煮面条。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01049","word":"kite","type":"名词","phonetic":"/kait/","meaning":"风筝","example":"Two children are flying a red kite in the park. / 两个孩子正在公园里放一只红色的风筝。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01050","word":"knee","type":"名词","phonetic":"/ni:/","meaning":"膝, 膝盖","example":"He hurt his knee while playing basketball last week. / 他上周打篮球时伤了膝盖。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01051","word":"knife","type":"名词","phonetic":"/naif/","meaning":"刀, 餐刀","example":"Please cut the cake with a clean knife. / 请用干净的刀切蛋糕。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01052","word":"knock","type":"动词","phonetic":"/nɔk/","meaning":"1. 敲, 敲打 2. (使)碰撞 n.敲, 击","example":"Someone is knocking at the door, so please open it. / 有人在敲门，请去开一下。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01053","word":"know","type":"动词","phonetic":"/nəu/","meaning":"知道, 了解 vt. 1. 认识 2. 精通","example":"Do you know the name of that tall building? / 你知道那座高楼的名字吗？","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01054","word":"knowledge","type":"名词","phonetic":"/'nɔliʤ/","meaning":"1. 知识, 学问 2. 认识, 知道","example":"Knowledge is the key to a better future for everyone. / 知识是每个人通向更好未来的钥匙。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01055","word":"labo(u)r","type":"名词","phonetic":"/'leɪbə/","meaning":"1. 劳动 2. 劳动力; 劳工","example":"The farmers' hard labor brought a good harvest this year. / 农民们的辛勤劳动带来了今年的好收成。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01056","word":"lack","type":"名词","phonetic":"/læk/","meaning":"缺乏, 不足（常与 of 连用）v. 缺乏, 不足","example":"The lack of sleep makes some students unable to focus in class. / 睡眠不足使一些学生上课无法集中注意力。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01057","word":"ladder","type":"名词","phonetic":"/'lædə/","meaning":"梯子, 阶梯","example":"He climbed the ladder to change the light in the hall. / 他爬上梯子换了大厅的灯。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01058","word":"lady","type":"名词","phonetic":"/'leidi/","meaning":"1. 女士, 夫人 2. (pl. ladies) 女厕所, 女盥洗室","example":"An old lady asked me the way to the nearest hospital. / 一位老太太向我问去最近医院的路。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01059","word":"lake","type":"名词","phonetic":"/leik/","meaning":"湖，湖泊","example":"We went boating on the lake last Sunday afternoon. / 上周日下午我们在湖上划船。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01060","word":"lamp","type":"名词","phonetic":"/læmp/","meaning":"灯","example":"Please turn on the lamp, because it is getting dark. / 请把灯打开，因为天快黑了。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01061","word":"land","type":"名词","phonetic":"/lænd/","meaning":"1.陆地, 地面 2. 土地, 田地 3. 国土, 国家 v. (使)登陆，（使）着陆","example":"The plane will land at the airport in twenty minutes. / 飞机将在二十分钟后降落在机场。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01062","word":"language","type":"名词","phonetic":"/'læŋgwiʤ/","meaning":"语言","example":"Learning a foreign language takes time, patience and practice. / 学一门外语需要时间、耐心和练习。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01063","word":"large","type":"形容词","phonetic":"/lɑ:ʤ/","meaning":"大的","example":"They live in a large house with a small garden. / 他们住在一栋带小花园的大房子里。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01064","word":"last","type":"形容词","phonetic":"/lɑ:st/","meaning":"1. 最后的, 惟一剩下的 2. 上一个的 adv. 1.最后 2. 最近一次, 上一次 vt. 持续，耐久","example":"This is the last chance for us to try again. / 这是我们再试一次的最后机会。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01065","word":"late","type":"形容词","phonetic":"/leit/","meaning":"1. 迟的 2. 晚的, 晚期的 3. 已故的 adv. 迟,晚","example":"Do not be late for the meeting again tomorrow. / 明天开会别再迟到了。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01066","word":"lately","type":"副词","phonetic":"/'leɪtli/","meaning":"最近，不久前","example":"I have not seen my old neighbour lately. / 我最近没见过我的老邻居。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01067","word":"later","type":"副词","phonetic":"/'leitə/","meaning":"1. 后来 2. 过一会儿 adj. 1. 后来的，以后的，后面的 2. 新近的 3. 晚年的","example":"I will call you later when I get home. / 我到家后再给你打电话。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01068","word":"laugh","type":"不及物动词","phonetic":"/lɑ:f/","meaning":"笑，讥笑","example":"The children laughed loudly at the funny cartoon. / 孩子们看着有趣的动画片大声笑了起来。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01069","word":"laugh at","type":"短语","phonetic":"","meaning":"嘲笑 n. 笑，笑声","example":"Never laugh at others when they make a mistake. / 别人犯错时决不要嘲笑他们。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01070","word":"law","type":"名词","phonetic":"/lɔ:/","meaning":"1.法律，法令 2. 法则，规律，定律","example":"Everyone must obey the law, including students. / 每个人都必须遵守法律，学生也不例外。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01071","word":"lawyer","type":"名词","phonetic":"/'lɔ:jə/","meaning":"律师","example":"Her brother works as a lawyer in a small town. / 她哥哥在一个小镇当律师。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01072","word":"lay","type":"及物动词","phonetic":"/lei/","meaning":"1. 放，搁 2. 铺设，砌（砖）","example":"Please lay the books on the desk before you leave. / 离开前请把书放在桌子上。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01073","word":"lay aside","type":"短语","phonetic":"","meaning":"1.把…搁置在一边 2. 储蓄","example":"Let us lay aside our phones and talk face to face. / 让我们把手机放到一边，面对面谈谈。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01074","word":"lay down","type":"短语","phonetic":"","meaning":"1. 放下 2．制定，拟定","example":"The manager will lay down a few rules for the new workers. / 经理将为新员工制定几条规则。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01075","word":"lay out","type":"短语","phonetic":"","meaning":"设计，制定","example":"They will lay out the new library with more reading seats. / 他们将把新图书馆设计成有更多阅读座位的样子。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01076","word":"lazy","type":"形容词","phonetic":"/'leizi/","meaning":"懒惰的, 懒散的","example":"He is too lazy to wash his own clothes. / 他太懒了，连自己的衣服都不洗。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01077","word":"lead","type":"动词","phonetic":"/li:d/","meaning":"1. 领导，引导 2. 领先，占首位","example":"She will lead the team in the coming singing contest. / 她将在即将到来的歌唱比赛中带领团队。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01078","word":"lead to","type":"短语","phonetic":"","meaning":"1. 通向 2. 导致，引起 n.带领，引导","example":"Eating too much sugar can lead to health problems. / 吃太多糖会导致健康问题。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01079","word":"leaf","type":"名词","phonetic":"/li:f/","meaning":"1.叶子 2.（书刊）的一张","example":"A yellow leaf fell slowly from the tall tree. / 一片黄叶从高树上慢慢飘落。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01080","word":"league","type":"名词","phonetic":"/li:g/","meaning":"1. 同盟，联盟 2. 联合会，社团","example":"Our school team joined the city football league this year. / 我们校队今年加入了市足球联赛。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01081","word":"learn","type":"动词","phonetic":"/lə:n/","meaning":"1. 学习，学 2. (of) 听到，获悉","example":"Children learn new words faster when they play games. / 孩子们做游戏时学新单词更快。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01082","word":"learn / know sth. by heart","type":"短语","phonetic":"","meaning":"强记；逐字记忆","example":"Students often learn long poems by heart before the exam. / 学生们常在考试前把长诗背下来。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01083","word":"least","type":"形容词","phonetic":"/li:st/","meaning":"最小的，最少的 adv. 最少，最小","example":"This is the least expensive way to travel around the city. / 这是环游这座城市最便宜的方式。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01084","word":"leave","type":"动词","phonetic":"/li:v/","meaning":"离开，出发 vt. 1. 留下，出发 2. 听任，让 3. 交付，委托 n. 准假，假期","example":"They will leave for Beijing early tomorrow morning. / 他们明天一早动身去北京。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01085","word":"leave behind","type":"短语","phonetic":"","meaning":"1. 留下 2. 忘记带","example":"Do not leave behind your umbrella on the bus. / 别把伞落在公交车上。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01086","word":"leave out","type":"短语","phonetic":"","meaning":"遗漏，略去","example":"Be careful not to leave out any important step. / 注意不要漏掉任何重要的步骤。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01087","word":"lecture","type":"名词","phonetic":"/'lekʧə/","meaning":"演讲，讲课","example":"The professor gave a lecture on Chinese tea culture. / 教授做了一场关于中国茶文化的讲座。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01088","word":"left","type":"形容词","phonetic":"/left/","meaning":"左，左边的; n. 左，左边","example":"Most people write with their right hand, but he uses his left hand. / 多数人用右手写字，但他用左手。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01089","word":"leg","type":"名词","phonetic":"/leg/","meaning":"腿","example":"My legs hurt after the long walk in the hills. / 在山里走了很远后，我的腿很疼。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01090","word":"lend","type":"动词","phonetic":"/lend/","meaning":"借给，贷（款）","example":"Could you lend me your dictionary for one afternoon? / 你能把词典借给我用一个下午吗？","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01091","word":"lend itself to","type":"短语","phonetic":"","meaning":"适宜于，对…有用","example":"The quiet garden can lend itself to reading and thinking. / 这个安静的花园适宜于读书和思考。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01092","word":"length","type":"名词","phonetic":"/leŋθ/","meaning":"1. 长，长度 2. 一段，一截","example":"He measured the length of the desk with a ruler. / 他用尺子量了桌子的长度。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01093","word":"less","type":"形容词","phonetic":"/les/","meaning":"更少的，更小的 adv. 更少地，更小地","example":"This year we spend less time on computer games than before. / 今年我们花在电脑游戏上的时间比以前少。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01094","word":"lesson","type":"名词","phonetic":"/'lesn/","meaning":"1. 功课 2. （一节）课 3.（pl.）课程 4. 教训","example":"We learned a useful lesson from that small failure. / 我们从那次小小的失败中学到了有用的一课。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01095","word":"let","type":"及物动词","phonetic":"/let/","meaning":"1. 允许, 让 2. 出租","example":"Let me help you carry the heavy box upstairs. / 让我帮你把重箱子搬上楼。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01096","word":"let alone","type":"短语","phonetic":"","meaning":"更不用说","example":"He can hardly walk, let alone run a kilometer. / 他几乎走不动，更不用说跑一公里了。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01097","word":"let out","type":"短语","phonetic":"","meaning":"放掉","example":"He opened the cage and let out the little bird. / 他打开笼子，把那只小鸟放掉了。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01098","word":"letter","type":"名词","phonetic":"/'letə/","meaning":"1. 信, 函件 2. 字母，文字","example":"Lily wrote a long letter to her grandmother last week. / 莉莉上周给她奶奶写了一封长信。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01099","word":"level","type":"名词","phonetic":"/'levl/","meaning":"1. 水平 2. 级别，等级 adj. 水平的，平的","example":"Her English level has improved a lot since last term. / 从上学期开始，她的英语水平提高了不少。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01100","word":"library","type":"名词","phonetic":"/'laibrəri/","meaning":"图书馆, 藏书室","example":"The library is quiet and many students study there every day. / 图书馆很安静，每天都有很多学生在那里学习。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01101","word":"lie","type":"不及物动词","phonetic":"/lai/","meaning":"1. 躺 2. 平放 3. 说谎, 欺骗 n. 谎话, 谎言","example":"He likes to lie on the grass and watch the clouds. / 他喜欢躺在草地上看云。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01102","word":"lie in","type":"短语","phonetic":"","meaning":"在于","example":"The real problem may lie in the way we study English. / 真正的问题可能在于我们学习英语的方式。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01103","word":"life","type":"名词","phonetic":"/laif/","meaning":"1. 生命 2. 生物 3. 一生，生涯","example":"Reading good books can make our life more colourful. / 读好书能让我们的生活更加丰富多彩。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01104","word":"lift","type":"不及物动词","phonetic":"/lift/","meaning":"（使）升起，举起 vi. 消散 n. 1. \\[英\\] 电梯 2.上升，升力","example":"The heavy box is too difficult for one person to lift. / 这个沉重的箱子一个人很难搬得起来。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01105","word":"light","type":"名词","phonetic":"/lait/","meaning":"1. 光，光亮 2. 光源，灯 v. 1. 点（火），点燃 2.（使）变亮，照亮 adj. 1. 轻的 2. 轻松的 3.（颜色）浅的 4. 光亮的","example":"Please turn off the light before you leave the classroom. / 离开教室前请把灯关掉。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01106","word":"like","type":"动词","phonetic":"/laik/","meaning":"1. 喜欢 2. 希望，想要 prep. 好像，如，跟…一样 adj. 相似的，同样的","example":"Most children like playing games in the park after school. / 大多数孩子喜欢放学后到公园里玩游戏。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01107","word":"limit","type":"名词","phonetic":"/'limit/","meaning":"界线，限度 vt. (to) 限制，限定","example":"We should limit the time we spend on mobile phones. / 我们应该限制每天玩手机的时间。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01108","word":"line","type":"名词","phonetic":"/lain/","meaning":"1. 线，绳 2．路线，航线 3. 排，行 4. 线路，电线 5. 界线，边线 v. 排队","example":"Please stand in line and wait for your turn quietly. / 请排队，安静地等待轮到你。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01109","word":"lion","type":"名词","phonetic":"/'laiən/","meaning":"狮子","example":"A lion was sleeping quietly under the big tree. / 一头狮子正在大树下安静地睡觉。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01110","word":"lip","type":"名词","phonetic":"/lip/","meaning":"嘴唇","example":"Her lips turned red in the cold winter wind. / 在寒冷的冬风里，她的嘴唇冻得发红。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01111","word":"list","type":"名词","phonetic":"/list/","meaning":"表, 清单 vt. 把…编列成表, 列于表上","example":"Please make a list of the books you want to read. / 请把你想读的书列成一张清单。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01112","word":"listen","type":"不及物动词","phonetic":"/'lisn/","meaning":"听","example":"We should listen carefully when the teacher explains grammar. / 老师讲语法的时候，我们应该认真听讲。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01113","word":"listen to sth. / sb.","type":"短语","phonetic":"","meaning":"1. 听 2. 听从","example":"Students must listen to the teacher and take careful notes. / 学生必须听老师的话，并认真做笔记。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01114","word":"litre","type":"名词","phonetic":"/'li:tə/","meaning":"(=liter)升(容量单位)","example":"Please buy two litres of milk on your way home. / 请在你回家的路上去买两升牛奶。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01115","word":"little","type":"形容词","phonetic":"/'litl/","meaning":"1. 小的 2. 很少的，几乎没有的 n. 没有多少，少量 adv. 几乎不","example":"There is little time left, so we must hurry up. / 剩下的时间不多了，我们得赶紧。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01116","word":"live","type":"不及物动词","phonetic":"/liv/","meaning":"1. 居住 2. 生活，生存 3. 过生活 adj. 1. 活的, 有生命的 2．实况的","example":"Many old people like to live in the quiet countryside. / 许多老人喜欢住在安静的乡下。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01117","word":"lively","type":"形容词","phonetic":"/'laivli/","meaning":"1. 活泼的, 活跃的 2. 栩栩如生的, 真实的","example":"The children look lively and happy in the playground. / 孩子们在操场上显得活泼又开心。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01118","word":"live through","type":"短语","phonetic":"","meaning":"度过，经受","example":"She helped the family live through the coldest winter. / 她帮助一家人度过了最寒冷的那个冬天。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01119","word":"live up to","type":"短语","phonetic":"","meaning":"做到，不辜负","example":"We should live up to the hopes of our parents. / 我们应该努力做到不辜负父母的期望。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01120","word":"living","type":"形容词","phonetic":"/'liviŋ/","meaning":"1. 活（着）的，生活的 2. 有生命力的，生动活泼的 n. 生计，生活","example":"All living things need clean water and fresh air. / 一切生物都需要干净的水和新鲜的空气。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01121","word":"load","type":"动词","phonetic":"/ləud/","meaning":"装（货），装载 n. 装载（量），负荷（量）","example":"The workers load the boxes onto the truck every morning. / 工人们每天早上把箱子装到卡车上。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01122","word":"lock","type":"名词","phonetic":"/lɔk/","meaning":"锁; v. 锁, 锁上","example":"Please lock the door when you leave the office. / 离开办公室时请把门锁上。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01123","word":"lonely","type":"形容词","phonetic":"/'ləunli/","meaning":"孤独的, 寂寞的","example":"Old people often feel lonely when their children are away. / 孩子们不在身边时，老人常常感到孤独。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01124","word":"long","type":"形容词","phonetic":"/lɔŋ/","meaning":"1. 长的，远的 2. 长久的，长期的 adv. 长久，长期地","example":"It takes a long time to learn a foreign language well. / 要把一门外语学好需要很长时间。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01125","word":"look","type":"不及物动词","phonetic":"/luk/","meaning":"1. (at) 看，望 2. 显得，好像 n. 1. (at) 看，望 2. 外表，样子","example":"Please look at the blackboard and take notes carefully. / 请看黑板，认真记笔记。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01126","word":"look after","type":"短语","phonetic":"","meaning":"照管，照料","example":"She helps her mother look after her little brother. / 她帮妈妈照看小弟弟。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01127","word":"look back","type":"短语","phonetic":"","meaning":"回顾","example":"When I look back on my school days, I feel happy. / 回想在学校的日子，我感到很幸福。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01128","word":"look down on/upon","type":"短语","phonetic":"","meaning":"看不起，轻视","example":"We should not look down on those who do simple work. / 我们不应该看不起做普通工作的人。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01129","word":"look for","type":"短语","phonetic":"","meaning":"寻找","example":"Let us look for a better way to solve this problem. / 让我们找一个更好的办法来解决这个问题。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01130","word":"look forward to","type":"短语","phonetic":"","meaning":"盼望，期望","example":"I look forward to hearing from you soon. / 我期待很快收到你的回信。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01131","word":"look in","type":"短语","phonetic":"","meaning":"顺便看望","example":"I will look in on my grandmother this weekend. / 这个周末我要顺便去看望奶奶。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01132","word":"look into","type":"短语","phonetic":"","meaning":"调查，观察","example":"The school will look into the matter and give us an answer. / 学校会调查这件事，并给我们一个答复。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01133","word":"look out","type":"短语","phonetic":"","meaning":"留神，提防","example":"Look out! The road is very wet and slippery today. / 当心！今天路面又湿又滑。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01134","word":"look over","type":"短语","phonetic":"","meaning":"检查","example":"Please look over your answers before you hand in the paper. / 交卷前请检查一遍你的答案。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01135","word":"look through","type":"短语","phonetic":"","meaning":"仔细查看","example":"He likes to look through old photos on rainy afternoons. / 他喜欢在下雨的午后翻看旧照片。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01136","word":"look up","type":"短语","phonetic":"","meaning":"查阅，查考","example":"You can look up new words in this small dictionary. / 你可以用这本小词典查生词。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01137","word":"lose","type":"及物动词","phonetic":"/lu:z/","meaning":"1. 丢，丢失 2. 迷（路）3. 输去，负 vi. （钟，表）走慢","example":"Be careful not to lose your keys on the crowded bus. / 小心不要在拥挤的公交车上丢了钥匙。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01138","word":"lose one’s head","type":"短语","phonetic":"","meaning":"不知所措","example":"Do not lose your head when the exam paper looks difficult. / 试卷看起来很难时，不要不知所措。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01139","word":"loss","type":"名词","phonetic":"/lɔs/","meaning":"1. 丢失，遗失 2. 损失，亏损","example":"The loss of his old dog made the whole family sad. / 失去那只老狗让全家人都很难过。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01140","word":"lot","type":"名词","phonetic":"/lɔt/","meaning":"1. 许多 2.（抽）签","example":"A lot of students take part in the singing contest. / 很多学生参加了这次歌唱比赛。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01141","word":"loud","type":"形容词","phonetic":"/laud/","meaning":"大声的，响亮的","example":"The music was too loud, so we could not talk. / 音乐声太大了，我们没法说话。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01142","word":"love","type":"及物动词","phonetic":"/lʌv/","meaning":"1. 爱, 热爱 2. 爱好, 喜欢 n.爱, 热爱","example":"Many children love reading stories before they go to bed. / 许多孩子喜欢在睡前读故事。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01143","word":"lovely","type":"形容词","phonetic":"/'lʌvli/","meaning":"1. 可爱的, 好看的 2. 愉快的","example":"What a lovely garden you have behind your house! / 你家屋后有一个多么可爱的花园啊！","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01144","word":"low","type":"形容词","phonetic":"/ləu/","meaning":"低的; 低劣的，低级的","example":"The price of fresh fruit is rather low this autumn. / 今年秋天新鲜水果的价格相当低。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01145","word":"luck","type":"名词","phonetic":"/lʌk/","meaning":"1. 运气 2. 好运","example":"Good luck with your English exam tomorrow morning! / 祝你明天早上的英语考试好运！","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01146","word":"lunch","type":"名词","phonetic":"/lʌnʧ/","meaning":"午餐","example":"We usually have lunch in the school dining hall. / 我们通常在学校食堂吃午饭。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01147","word":"machine","type":"名词","phonetic":"/mə'ʃi:n/","meaning":"机器, 机械 vt. 用机器加工","example":"This washing machine has worked well for over ten years. / 这台洗衣机已经正常用了十多年。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01148","word":"mad","type":"形容词","phonetic":"/mæd/","meaning":"1. 发疯的, 狂怒的 2. 狂热的, 着迷的","example":"He was mad at me for breaking his favourite cup. / 他因为我打碎了他最喜欢的杯子而生我的气。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01149","word":"magazine","type":"名词","phonetic":"/'mægə'zi:n/","meaning":"杂志, 期刊","example":"She reads an English magazine to improve her reading skills. / 她读一本英语杂志来提高阅读能力。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01150","word":"mail","type":"名词","phonetic":"/meil/","meaning":"邮件 vt. 邮寄","example":"I will mail the letter to my teacher this afternoon. / 我今天下午要把信寄给老师。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01151","word":"mailbox","type":"名词","phonetic":"/'meilbɔks/","meaning":"邮箱","example":"There is a red mailbox at the corner of our street. / 我们街角有一个红色的邮箱。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01152","word":"main","type":"形容词","phonetic":"/mein/","meaning":"主要的","example":"The main reason for his failure is that he never plans his time. / 他失败的主要原因是从不规划自己的时间。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01153","word":"mainly","type":"副词","phonetic":"/'meɪnli/","meaning":"大体上, 主要地","example":"Our English class is mainly made up of group work and games. / 我们的英语课主要由小组活动和游戏组成。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01154","word":"make","type":"及物动词","phonetic":"/meik/","meaning":"1. 做，制造 2. 准备，布置 3. 使，使得 4.获得，挣得 5. 总计，等于 n.（产品）制造方法，（产品）来源","example":"Let us make a small cake for our mother's birthday. / 我们一起给妈妈做一个小生日蛋糕吧。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01155","word":"make an impression on","type":"短语","phonetic":"","meaning":"给…留下印象","example":"A kind teacher can make an impression on students for years. / 和善的老师能在多年里给学生留下深刻印象。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01156","word":"make for","type":"短语","phonetic":"","meaning":"1. 走向，驶 2. 有助于，有利于","example":"Hard work and patience make for a better future. / 勤奋和耐心有助于创造更美好的未来。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01157","word":"make out","type":"短语","phonetic":"","meaning":"1. 辨认，区分 2. 理解","example":"It was so dark that I could not make out the words. / 天太黑了，我看不清上面的字。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01158","word":"make sure of / that","type":"短语","phonetic":"","meaning":"确信，确定，务必","example":"Please make sure that all the windows are closed. / 请确保所有的窗户都关好了。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01159","word":"make the best of","type":"短语","phonetic":"","meaning":"充分利用","example":"We should make the best of our time at college. / 我们应该充分利用在大学里的时间。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01160","word":"make up","type":"短语","phonetic":"","meaning":"1. 组成，构成 2. 弥补 3. 化妆","example":"Six students make up the small reading group this term. / 这学期六个学生组成了这个小型读书小组。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01161","word":"make up for","type":"短语","phonetic":"","meaning":"补偿，弥补","example":"He studies harder to make up for the lost time. / 他更加努力地学习，以弥补失去的时间。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01162","word":"make up one’s mind to do sth.","type":"短语","phonetic":"","meaning":"下决心做某事","example":"You should make up your mind to finish the task today. / 你应该下定决心今天就把任务完成。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01163","word":"man","type":"名词","phonetic":"/mæn/","meaning":"男人; 人类, 人","example":"The old man told us a funny story about his childhood. / 那位老人给我们讲了一个关于他童年的有趣故事。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01164","word":"manage","type":"动词","phonetic":"/'mæniʤ/","meaning":"1. 经营，管理, 处理 2. 设法，对付 vt. 操纵，运用","example":"She manages to finish her homework before dinner every day. / 她每天都在晚饭前设法完成作业。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01165","word":"manager","type":"名词","phonetic":"/'mæniʤə/","meaning":"经理, 管理人","example":"The manager asked us to arrive at the office on time. / 经理要求我们准时到办公室。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01166","word":"many","type":"形容词","phonetic":"/'meni/","meaning":"许多的，多的 pro. 许多人, 许多","example":"Many students in our school join the volunteer club. / 我们学校有很多学生加入了志愿者社团。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01167","word":"many a","type":"短语","phonetic":"","meaning":"许多","example":"Many a student has learned to cook during the long holiday. / 许多学生在漫长的假期里学会了做饭。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01168","word":"map","type":"名词","phonetic":"/mæp/","meaning":"地图, 图","example":"We used a map to find the small museum in the old town. / 我们靠一张地图在古镇里找到了那个小博物馆。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01169","word":"March","type":"名词","phonetic":"/mɑ:ʧ/","meaning":"三月","example":"The new term usually begins in March every year. / 新学期通常在每年三月开始。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01170","word":"mark","type":"名词","phonetic":"/mɑ:k/","meaning":"1. 痕迹, 斑点 2. 记号，符号 3（. 考试等的）的分数 vt. 1. 计分，打分 2. 标明，作记号于","example":"The teacher put a red mark on my exercise book. / 老师在我的练习本上画了一个红色的记号。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01171","word":"marvel(l)ous","type":"形容词","phonetic":"/'mɑrvələs/","meaning":"奇迹般的，惊人的，妙极的","example":"We had a marvelous time at the school sports meeting. / 我们在学校运动会上玩得非常开心。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01172","word":"master","type":"名词","phonetic":"/'mɑ:stə/","meaning":"男主人, 雇主; 师傅，能手; 硕士 vt. 精通, 掌握","example":"It takes years of practice to master a musical instrument. / 要精通一种乐器需要多年的练习。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01173","word":"match","type":"名词","phonetic":"/mæʧ/","meaning":"火柴; 比赛, 竞赛 v. 相配, 相称","example":"The football match will start at four in the afternoon. / 这场足球比赛将在下午四点开始。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01174","word":"matter","type":"名词","phonetic":"/'mætə/","meaning":"1. 物质 2. 麻烦事，毛病 3. 事件, 问题 vi. 有关系, 要紧","example":"It does not matter if you make a small mistake. / 犯个小错误没关系，不必害怕。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01175","word":"May","type":"名词","phonetic":"/mei/","meaning":"五月","example":"The roses in our school garden open in May. / 我们学校花园里的玫瑰在五月开放。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01176","word":"maybe","type":"副词","phonetic":"/'meibi:/","meaning":"大概, 或许","example":"Maybe we should ask our teacher for some advice. / 也许我们应该向老师请教一些建议。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01177","word":"me","type":"代词","phonetic":"/mi:/","meaning":"\\[I 的宾格\\] 我","example":"Could you please pass me the salt at dinner? / 晚饭时请把盐递给我好吗？","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01178","word":"meal","type":"名词","phonetic":"/mi:l/","meaning":"一餐, 膳食","example":"We should eat three healthy meals at regular times. / 我们应该按时吃三顿健康的饭。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01179","word":"mean","type":"及物动词","phonetic":"/mi:n/","meaning":"1. 表示…意思，意思 2. 意欲，打算 adj. 1.卑鄙的 2. 吝啬的, 小气的 3. 平均的 n. 平均值","example":"What does this new word mean in the sentence? / 这个生词在这句话里是什么意思？","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01180","word":"meat","type":"名词","phonetic":"/mi:t/","meaning":"(食用)肉","example":"My grandfather eats little meat and many fresh vegetables. / 我爷爷很少吃肉，吃很多新鲜蔬菜。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01181","word":"medical","type":"形容词","phonetic":"/'medikəl/","meaning":"1. 医学的, 医疗的 2. 内科的","example":"Every student should have a medical check once a year. / 每个学生每年都应该做一次体检。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01182","word":"medicine","type":"名词","phonetic":"/'medisin/","meaning":"内服药; 医学, 内科学","example":"The doctor told him to take the medicine after meals. / 医生让他饭后吃药。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01183","word":"meet","type":"动词","phonetic":"/mi:t/","meaning":"1. (with)遇见，碰到 2. 会见，会谈 vt. 1. 迎接 2. 满足，符合","example":"Let us meet at the school gate at seven tomorrow. / 我们明天七点在校门口见吧。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01184","word":"meeting","type":"名词","phonetic":"/'mi:tiŋ/","meaning":"1. 会议, 集会 2. 会见, 会合","example":"The class meeting will be held in our classroom tomorrow. / 班会明天将在我们的教室里举行。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01185","word":"member","type":"名词","phonetic":"/'membə/","meaning":"成员, 会员","example":"She is an active member of the school music club. / 她是学校音乐社团的积极成员。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01186","word":"memory","type":"名词","phonetic":"/'meməri/","meaning":"1. 记忆, 记忆力 2. 回忆 3. 存储（器）","example":"I have a clear memory of my first day at school. / 我对上学的第一天有清晰的记忆。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01187","word":"mend","type":"及物动词","phonetic":"/mend/","meaning":"修补，缝补","example":"My mother helped me mend my old school bag. / 妈妈帮我补好了我的旧书包。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01188","word":"message","type":"名词","phonetic":"/'mesiʤ/","meaning":"消息, 信息","example":"Please leave a short message if I am not at home. / 如果我不在家，请留个简短的留言。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01189","word":"metal","type":"名词","phonetic":"/'metəl/","meaning":"金属","example":"The box is made of light metal and is easy to carry. / 这个箱子是用轻金属做的，很容易搬。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01190","word":"meter/-tre","type":"名词","phonetic":"/'mi:tə/","meaning":"米, 公尺","example":"The new bridge is about two hundred meters long. / 这座新桥大约有两百米长。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01191","word":"method","type":"名词","phonetic":"/'meθəd/","meaning":"方式，方法","example":"This method helps us remember new words more quickly. / 这个方法能帮助我们更快地记住生词。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01192","word":"midday","type":"名词","phonetic":"/mɪd'deɪ/","meaning":"正午","example":"The sun is very strong at midday in summer. / 夏天正午的阳光非常强烈。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01193","word":"middle","type":"名词","phonetic":"/'midl/","meaning":"中间, 当中 adj.中间的, 中部的","example":"The teacher stood in the middle of the classroom. / 老师站在教室的中间。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01194","word":"midnight","type":"名词","phonetic":"/'midnait/","meaning":"午夜","example":"Many students go to bed after midnight and feel tired. / 许多学生午夜后才睡觉，感到很疲倦。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01195","word":"might","type":"动词","phonetic":"/mait/","meaning":"aux. 1. \\[may 的过去式\\]2. 可能，会 n. 力量,威力, 能力","example":"Take an umbrella, or you might get wet in the rain. / 带把伞吧，不然你可能会被雨淋湿。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01196","word":"mile","type":"名词","phonetic":"/mail/","meaning":"英里","example":"The small village is about a mile from the river. / 这个小村庄离河边大约一英里。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01197","word":"milk","type":"名词","phonetic":"/milk/","meaning":"乳, 牛奶; v. 挤(奶)","example":"A glass of warm milk helps me sleep better at night. / 一杯温牛奶能让我晚上睡得更好。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01198","word":"million","type":"数词","phonetic":"/'miljən/","meaning":"百万, 百万个 n. (pl.) (of) 无数","example":"Millions of people watch the same show on television. / 数百万人在电视上观看同一个节目。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01199","word":"mind","type":"名词","phonetic":"/maind/","meaning":"1. 头脑, 精神 2. 记忆 vi. 1. 注意，留心 2. 介意, 反对","example":"Would you mind closing the window, please? / 请你把窗户关上好吗？","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01200","word":"mine","type":"代词","phonetic":"/main/","meaning":"我的(东西)n. 1. 矿, 矿山 2. 地雷, 水雷 v. 1. 采矿 2. 布雷","example":"That blue umbrella near the door is mine, not yours. / 门边那把蓝伞是我的，不是你的。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01201","word":"minute","type":"名词","phonetic":"/'minit/","meaning":"1. 分, 分钟 2. 一会儿，一瞬间","example":"Please wait a minute while I find my notebook. / 请稍等一分钟，我找一下笔记本。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01202","word":"mirror","type":"名词","phonetic":"/'mirə/","meaning":"镜子","example":"She looked in the mirror and smiled at herself. / 她照了照镜子，对自己笑了。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01203","word":"miss","type":"名词","phonetic":"/mis/","meaning":"\\[M-\\] 小姐 v. 未击中 vt. 1. 错过, 未赶上 2.惦念 3. (out) 漏掉，省掉","example":"I miss my old friends from middle school very much. / 我非常想念中学时的老朋友们。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01204","word":"mistake","type":"名词","phonetic":"/mis'teik/","meaning":"错误, 过失 v. 弄错, 误解","example":"Everyone makes a mistake sometimes, so do not be afraid. / 每个人有时都会犯错，所以不要害怕。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01205","word":"mistake … for …","type":"短语","phonetic":"","meaning":"把...误认为 …","example":"Do not mistake a stranger for your old classmate. / 不要把陌生人误认为你的老同学。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01206","word":"mix","type":"动词","phonetic":"/miks/","meaning":"1. 使混和 2. 混淆","example":"Mix the eggs with the flour and stir them well. / 把鸡蛋和面粉混合，搅拌均匀。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01207","word":"mode","type":"名词","phonetic":"/məud/","meaning":"方式, 样式","example":"Walking is a healthy mode of travel for short trips. / 短途出行时，步行是一种健康的出行方式。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01208","word":"model","type":"名词","phonetic":"/'mɔdl/","meaning":"1. 样式, 型 2. 模范, 典型 3. 模型, 原型,模特儿","example":"Our teacher is a good model for all the students. / 我们的老师是全体学生的好榜样。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01209","word":"modern","type":"形容词","phonetic":"/'mɔdən/","meaning":"现代的, 新式的","example":"Modern technology plays an important role in people's lives. / 现代技术在人们的生活中起着越来越重要的作用。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01210","word":"moment","type":"名词","phonetic":"/'məumənt/","meaning":"片刻, 瞬间","example":"He stood there for a moment and then smiled. / 他在那里站了一会儿，然后笑了。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01211","word":"Monday","type":"名词","phonetic":"/'mʌndi/","meaning":"星期一","example":"We have two English classes every Monday morning. / 我们每周一上午有两节英语课。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01212","word":"money","type":"名词","phonetic":"/'mʌni/","meaning":"货币, 钱","example":"Many young people spend too much money on online shopping. / 许多年轻人在网购上花太多钱。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01213","word":"monkey","type":"名词","phonetic":"/'mʌŋki/","meaning":"猴子","example":"The little monkey jumped from one tree to another. / 那只小猴子从一棵树跳到另一棵树上。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01214","word":"month","type":"名词","phonetic":"/mʌnθ/","meaning":"月","example":"The new library will open next month. / 新图书馆将在下个月开放。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01215","word":"monthly","type":"形容词","phonetic":"/'mʌnθli/","meaning":"每月的 adv. 每月一次 n.月刊","example":"Our class holds a monthly meeting to talk about study. / 我们班每月开一次班会讨论学习。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01216","word":"moon","type":"名词","phonetic":"/mu:n/","meaning":"月球, 月亮; 卫星","example":"The moon is bright and the night sky looks beautiful. / 月亮很亮，夜空看起来很美。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01217","word":"more","type":"形容词","phonetic":"/mɔ:/","meaning":"更多的 n.更多 adv.更, 更多","example":"We need more time and more practice to improve our English. / 我们需要更多时间和更多练习来提高英语。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01218","word":"more and more","type":"短语","phonetic":"","meaning":"越来越（多）","example":"More and more people are concerned about the problem of air pollution. / 越来越多的人开始关注空气污染问题。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01219","word":"more or less","type":"短语","phonetic":"","meaning":"或多或少","example":"His answer is more or less right, but not perfect. / 他的答案或多或少是对的，但不算完美。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01220","word":"morning","type":"名词","phonetic":"/'mɔ:niŋ/","meaning":"早晨, 上午","example":"I read English aloud for twenty minutes every morning. / 我每天早上朗读英语二十分钟。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01221","word":"most","type":"形容词","phonetic":"/məust/","meaning":"1. 最多的 2. 多数的, 大部分的 adv. 1.最, 最多 2. 很, 十分 n.大多数, 大部分","example":"Most students in our class like the new English teacher. / 我们班大多数学生喜欢新来的英语老师。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01222","word":"mostly","type":"副词","phonetic":"/'məʊstli/","meaning":"主要地, 大部分","example":"The book is mostly about how to learn English well. / 这本书主要是讲怎样学好英语的。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01223","word":"mother","type":"名词","phonetic":"/'mʌðə/","meaning":"母亲","example":"My mother always gets up early to make breakfast. / 我妈妈总是很早起床做早饭。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01224","word":"mountain","type":"名词","phonetic":"/'mauntin/","meaning":"1. 山 2. (pl.) 山脉","example":"We climbed the mountain and enjoyed the fresh air. / 我们爬上山，呼吸着新鲜空气。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01225","word":"mouse","type":"名词","phonetic":"/maus/","meaning":"鼠; 鼠标","example":"A little mouse ran across the kitchen floor last night. / 昨晚一只小老鼠从厨房地板上跑过。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01226","word":"mouth","type":"名词","phonetic":"/mauθ/","meaning":"口, 嘴","example":"Please do not talk with your mouth full of food. / 请不要嘴里塞满食物说话。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01227","word":"move","type":"及物动词","phonetic":"/mu:v/","meaning":"1. 移动，搬动 2. 感动, 激动 vi. 1. 迁移,搬家 2. 活动 n. 移动, 活动","example":"They will move to a new flat near the school. / 他们将要搬到学校附近的一套新房子。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01228","word":"movement","type":"名词","phonetic":"/'mu:vmənt/","meaning":"运动, 活动; 移动，迁移","example":"This exercise helps the free movement of your arms. / 这个练习有助于手臂的自由活动。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01229","word":"movie","type":"名词","phonetic":"/'mu:vi/","meaning":"电影","example":"We watched a funny movie together last Saturday evening. / 上周六晚上我们一起看了一部有趣的电影。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01230","word":"much","type":"形容词","phonetic":"/mʌʧ/","meaning":"许多的, 大量的 adv. 1. 非常, 很 2. …多, 更加 n. 许多, 大量","example":"He does not have much free time during the term. / 这学期他没有多少空闲时间。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01231","word":"music","type":"名词","phonetic":"/'mju:zik/","meaning":"音乐","example":"Soft music can help us relax after a long day. / 轻柔的音乐能帮助我们在忙碌一天后放松。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01232","word":"musical","type":"形容词","phonetic":"/'mjuzɪkəl/","meaning":"1. 音乐的 2. 悦耳的","example":"She comes from a musical family and plays the piano well. / 她出身音乐家庭，钢琴弹得很好。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01233","word":"must","type":"动词","phonetic":"/mʌst/","meaning":"aux. 1. 必须, 应当 2. 很可能, 一定","example":"You must finish your homework before you watch TV. / 你必须先完成作业才能看电视。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01234","word":"my","type":"代词","phonetic":"/mai/","meaning":"(I 的所有格)我的","example":"My sister studies in a middle school near our home. / 我姐姐在我们家附近的一所中学读书。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01235","word":"myself","type":"代词","phonetic":"/mai'self/","meaning":"我自己; 我亲自, 我本人","example":"I finished the whole project by myself last week. / 上周我独自完成了整个项目。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01236","word":"nail","type":"名词","phonetic":"/neil/","meaning":"指甲；钉，钉子; vt. 钉，将…钉牢","example":"He hit the nail with a hammer and fixed the chair. / 他用锤子敲钉子，把椅子修好了。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01237","word":"name","type":"名词","phonetic":"/neim/","meaning":"1. 名字 2. 名义 v. 说出…的名字","example":"Please write your name at the top of the answer sheet. / 请把你的名字写在答题卡的上方。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01238","word":"name after","type":"短语","phonetic":"","meaning":"命名","example":"In some families, parents name a child after a grandparent. / 在一些家庭里，父母用祖辈的名字给孩子取名。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01239","word":"narrow","type":"形容词","phonetic":"/'nærəu/","meaning":"狭窄的，严密的，有限的，气量小的，眼光短浅的","example":"The street is too narrow for two cars to pass. / 这条街太窄，两辆车无法通过。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01240","word":"nation","type":"名词","phonetic":"/'neiʃən/","meaning":"国家, 民族","example":"The whole nation celebrated the great success of the team. / 全国人民都在庆祝这支队伍的巨大成功。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01241","word":"national","type":"形容词","phonetic":"/'næʃənl/","meaning":"国家的，民族的; 国立(有)的,全国性的","example":"Tomorrow is a national holiday and all offices are closed. / 明天是全国假日，所有办公室都关门。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01242","word":"native","type":"形容词","phonetic":"/'neitiv/","meaning":"本国的，出生地的，本地的，土产的，土著的; 与生俱来的，天赋的, n. 本地人，本国人，土产","example":"She speaks English as well as a native speaker does. / 她的英语说得和本族语者一样好。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01243","word":"natural","type":"形容词","phonetic":"/'næʧərəl/","meaning":"自然的，自然界的，天生的，天赋的","example":"It is natural for children to make mistakes while learning. / 孩子在学习中犯错是很自然的。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01244","word":"natural resources","type":"短语","phonetic":"","meaning":"自然资源","example":"We should protect natural resources for future generations. / 我们应该为子孙后代保护自然资源。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01245","word":"near","type":"介词","phonetic":"/niə/","meaning":"在…近旁; adv. (时间，空间方面)近，不远；adj. 亲近的，亲密的，近","example":"Our school is near the river and the bus stop. / 我们学校靠近河边和公交站。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01246","word":"nearly","type":"副词","phonetic":"/'niəli/","meaning":"几乎，密切地","example":"I have nearly finished my homework for tomorrow. / 我几乎做完明天要交的作业了。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01247","word":"neat","type":"形容词","phonetic":"/ni:t/","meaning":"整洁的，灵巧的，优雅的","example":"Her bedroom is always neat and clean. / 她的卧室总是整洁干净。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01248","word":"necessary","type":"形容词","phonetic":"/'nesisəri/","meaning":"1. 必须的；必要的(后跟 that 从句要用虚拟语气)2. 必定的，必然的","example":"It is necessary that every student hand in the report on time. / 每个学生按时交报告是必要的。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01249","word":"neck","type":"名词","phonetic":"/nek/","meaning":"颈，脖子","example":"He hurt his neck while playing basketball yesterday. / 他昨天打篮球时伤了脖子。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01250","word":"need","type":"及物动词","phonetic":"/ni:d/","meaning":"（实义动词）需要，要 n. 1. 需要，需求 2.必须 3. 不幸，逆境","example":"We need more time to prepare for the final exam. / 我们需要更多时间准备期末考试。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01251","word":"needle","type":"名词","phonetic":"/'ni:dl/","meaning":"针，缝衣针；针叶；针状物","example":"She used a needle and thread to mend her coat. / 她用针线补好了自己的外套。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01252","word":"neighbo(u)r","type":"名词","phonetic":"/'neibə/","meaning":"邻居，邻国 neighbo(u)rhood n. 街坊, 四邻; 街道; 附近地区,邻近","example":"My neighbour often helps me carry heavy things upstairs. / 我的邻居经常帮我搬重东西上楼。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01253","word":"neither","type":"代词","phonetic":"/'naiðə/","meaning":"两者都不，不…也不… neither…nor 既不...也不...","example":"Neither of the two answers is correct. / 两个答案都不正确。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01254","word":"nervous","type":"形容词","phonetic":"/'nə:vəs/","meaning":"1. 焦虑的，紧张不安的；神经过敏的 2. 神经系统的 3. 害怕的，胆怯的","example":"Many students feel nervous before an important exam. / 许多学生在重要考试前感到紧张。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01255","word":"net","type":"名词","phonetic":"/net/","meaning":"网，网状物；通信网 adj. 净的，纯的","example":"The fishermen pulled the heavy net out of the water. / 渔民们把沉重的网从水里拉了出来。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01256","word":"never","type":"副词","phonetic":"/'nevə/","meaning":"1. 从未，永不，决不 2. 不，不要","example":"I will never forget the help you gave me. / 我永远不会忘记你给我的帮助。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01257","word":"new","type":"形容词","phonetic":"/njʉ:/","meaning":"1. 新的，新近的 2. 更新的，新鲜的，新颖的","example":"Our teacher gave us a new way to remember words. / 老师给了我们一种记单词的新方法。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01258","word":"news","type":"名词","phonetic":"/nju:z/","meaning":"新闻，消息","example":"The good news made the whole class happy. / 这个好消息让全班都很高兴。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01259","word":"newspaper","type":"名词","phonetic":"/ˌnju:s'peipə/","meaning":"报纸","example":"My grandfather reads the newspaper every morning at home. / 我爷爷每天早上在家读报纸。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01260","word":"next","type":"形容词","phonetic":"/nekst/","meaning":"（常与 to 连用）最近的，邻接的，下一个的 2. 紧接着的；其次的 adv. 1.（与 to 连用）几乎，贴近 2. 下次，其次","example":"We will visit our grandparents next Sunday morning. / 我们下周日上午去看望祖父母。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01261","word":"nice","type":"形容词","phonetic":"/nais/","meaning":"好的，友善的；漂亮的；令人愉快的","example":"It is nice of you to help the old man. / 你帮助那位老人真是太好了。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01262","word":"night","type":"名词","phonetic":"/nait/","meaning":"夜晚，黑夜","example":"The city looks beautiful at night with all the lights. / 夜晚灯火通明时，这座城市很美。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01263","word":"nine","type":"数词","phonetic":"/nain/","meaning":"九，九个","example":"There are nine students in our reading group. / 我们的阅读小组有九名学生。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01264","word":"nineteen","type":"数词","phonetic":"/'nain'ti:n/","meaning":"十九的，十九，十九个","example":"Nineteen students took part in the speech contest. / 十九名学生参加了演讲比赛。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01265","word":"ninety","type":"数词","phonetic":"/'nainti/","meaning":"九十","example":"My grandfather is ninety years old but still very strong. / 我爷爷九十岁了，身体却还很壮。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01266","word":"ninth","type":"数词","phonetic":"/nainθ/","meaning":"第九","example":"Our classroom is on the ninth floor of the building. / 我们的教室在这栋楼的九层。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01267","word":"no","type":"形容词","phonetic":"/nəu/","meaning":"1. 没有 2. 绝非 3. 不准，不（允）许，不要","example":"There is no milk left in the fridge. / 冰箱里没有牛奶了。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01268","word":"noble","type":"形容词","phonetic":"/'nəubl/","meaning":"1. 高尚的，崇高的 2. 贵族的, 显贵的","example":"It is a noble act to help others without asking for anything. / 不求回报地帮助他人是高尚的行为。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01269","word":"nobody","type":"代词","phonetic":"/'nəubədi/","meaning":"没有人，无人","example":"Nobody knows the answer to this difficult question. / 没有人知道这个难题的答案。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01270","word":"nod","type":"动词","phonetic":"/nɔd/","meaning":"点头 n. 点头","example":"She gave me a friendly nod and went on reading. / 她友好地向我点了点头，继续看书。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01271","word":"no doubt","type":"短语","phonetic":"","meaning":"无疑地","example":"There is no doubt that exercise keeps us healthy. / 毫无疑问，锻炼能让我们保持健康。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01272","word":"noise","type":"名词","phonetic":"/nɔiz/","meaning":"声音，噪音；干扰","example":"The noise from the street kept me awake all night. / 街上的噪音让我整夜没睡。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01273","word":"noisy","type":"形容词","phonetic":"/'nɔizi/","meaning":"吵闹的, 喧闹的, 嘈杂的","example":"The classroom was too noisy for us to study well. / 教室太吵了，我们无法好好学习。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01274","word":"no less than","type":"短语","phonetic":"","meaning":"1. 决不少于 2. 不亚于，不次于","example":"No less than thirty students joined the clean-up activity. / 不少于三十名学生参加了清扫活动。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01275","word":"no matter + wh-word","type":"短语","phonetic":"","meaning":"无论…","example":"No matter which word you choose, the sentence must be clear. / 无论你选择哪个词，句子都必须清楚明白。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01276","word":"no more","type":"短语","phonetic":"","meaning":"不再","example":"No more time should be wasted on such useless talk. / 不应再把时间浪费在这种无用的谈话上。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01277","word":"no more than","type":"短语","phonetic":"","meaning":"1. 不过，仅仅 2. 和…一样不","example":"It takes no more than ten minutes to walk there. / 走到那里不超过十分钟。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01278","word":"none","type":"代词","phonetic":"/nʌn/","meaning":"1. （与 of 连用）毫无 2. 没有一个，无一 adv. （与 the 连用）毫不，一点也不","example":"None of the students knew the answer to the question. / 没有一个学生知道这个问题的答案。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01279","word":"noodle","type":"名词","phonetic":"/nu:dl/","meaning":"面条(常用复数)","example":"We had beef noodles and vegetables for lunch today. / 我们今天午饭吃了牛肉面和蔬菜。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01280","word":"noon","type":"名词","phonetic":"/nu:n/","meaning":"中午，正午；全盛期","example":"We usually have lunch at noon in the school dining hall. / 我们通常中午在学校食堂吃午饭。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01281","word":"nor","type":"连词","phonetic":"/nɔ:/","meaning":"（与 neither 连用）也不","example":"Neither Tom nor Lily was at the meeting yesterday. / 昨天汤姆和莉莉都没有到会。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01282","word":"north","type":"名词","phonetic":"/nɔ:θ/","meaning":"北，北方 adj. 北的，在北方的，向北的；来自北方的","example":"The wind from the north brought cold weather to the city. / 北风给这座城市带来了寒冷的天气。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01283","word":"northern","type":"形容词","phonetic":"/'nɔ:ðən/","meaning":"北的；北部的","example":"Many visitors come to the northern part of the country in autumn. / 许多游客在秋天来到这个国家的北部。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01284","word":"northwest","type":"名词","phonetic":"/nɔ:θ'west/","meaning":"西北，西北方；西北风 adj. 西北的，西北方的；向西北方的，位于西北方的","example":"The small village lies in the northwest of the province. / 这个小村庄位于该省的西北部。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01285","word":"nose","type":"名词","phonetic":"/nəuz/","meaning":"鼻子; (机头、车头、枪头等)突出部分","example":"The little boy touched his nose and laughed loudly. / 小男孩摸了摸鼻子，大声笑了起来。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01286","word":"no sooner … than","type":"短语","phonetic":"","meaning":"一…就，刚…便","example":"No sooner had I sat down than the bell rang. / 我刚坐下，铃声就响了。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01287","word":"not","type":"副词","phonetic":"/nɔt/","meaning":"（用于将词、句改为相反的意思）不","example":"She is not afraid of speaking in front of the class. / 她不怕在全班同学面前讲话。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01288","word":"not at all","type":"短语","phonetic":"","meaning":"一点也不","example":"I am not at all tired after the long walk. / 走了很长的路，我一点也不累。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01289","word":"note","type":"名词","phonetic":"/nəut/","meaning":"1. 笔记，记录；草稿；备忘录 2. 注释，按语 3. 短笺，便条 4. 纸币，钞票 vt. 1.（常与 down连用）注意； 记住，记下 2. 认识，注意到","example":"Please take notes while the teacher is speaking. / 老师讲课时请做笔记。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01290","word":"nothing","type":"代词","phonetic":"/'nʌθiŋ/","meaning":"没有什么，没有东西","example":"There is nothing more important than health and family. / 没有什么比健康和家庭更重要。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01291","word":"notice","type":"名词","phonetic":"/'nəutis/","meaning":"警告；通知，布告 2. 注意 vt. & vi.（常与 that, how 连用）注意到，看到，留心","example":"I noticed that she looked tired after the exam. / 我注意到她考试后看起来很疲惫。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01292","word":"noun","type":"名词","phonetic":"/naun/","meaning":"名词","example":"In this sentence, the word apple is a noun. / 在这个句子中，这个词是一个名词。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01293","word":"novel","type":"名词","phonetic":"/'nɔvəl/","meaning":"小说 adj. 新的, 新颖的, 新奇的, 独创的","example":"She finished reading the whole novel in two days. / 她两天就读完了整本小说。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01294","word":"November","type":"名词","phonetic":"/nəu'vembə/","meaning":"十一月（缩写 Nov.）","example":"The weather gets colder and colder in November. / 十一月的天气越来越冷。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01295","word":"now","type":"副词","phonetic":"/nau/","meaning":"1. 现在, 目前 2. 立刻，马上 3.（用于引起注意）","example":"We should stop talking and start working now. / 我们现在应该停止说话，开始工作。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01296","word":"nowadays","type":"副词","phonetic":"/'nauədeiz/","meaning":"（同过去相比较） 现在，现今，如今","example":"Nowadays more and more people pay attention to their health. / 如今越来越多的人关注自己的健康。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01297","word":"now that","type":"短语","phonetic":"","meaning":"既然","example":"Now that you have passed the exam, you can relax a little. / 既然你已经通过了考试，就可以稍微放松一下。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01298","word":"number","type":"名词","phonetic":"/'nʌmbə/","meaning":"1. 数，数字 2. 号, 号码（简写为 No. 或 no.）3. 数目，数量 vt. 1. 总计，共计；数以…计 2.标号，给…编号","example":"The number of students in our school is growing fast. / 我们学校的学生人数正在快速增长。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01299","word":"nurse","type":"名词","phonetic":"/nə:s/","meaning":"护士，保姆 vt. 护理，看护, 照料","example":"The nurse took good care of the old patient last night. / 昨晚护士细心地照顾了那位老年病人。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01300","word":"nut","type":"名词","phonetic":"/nʌt/","meaning":"1. 果核，坚果, 果仁 2. 螺母，螺丝帽 3. 难事，难题，难对付的人","example":"Squirrels hide nuts in the trees for the winter. / 松鼠把坚果藏在树上过冬。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01301","word":"ocean","type":"名词","phonetic":"/'əuʃən/","meaning":"海洋","example":"The ocean covers most of the surface of the earth. / 海洋覆盖了地球表面的大部分。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01302","word":"o'clock","type":"名词","phonetic":"/ə'klɔk/","meaning":"…点钟","example":"The meeting will start at eight o'clock tomorrow morning. / 会议将于明天上午八点开始。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01303","word":"October","type":"名词","phonetic":"/ɔk'təubə/","meaning":"十月（缩写 Oct.）","example":"We will have a sports meeting in October this year. / 今年十月我们将举行运动会。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01304","word":"of","type":"介词","phonetic":"/əv/","meaning":"1.（表所属、性质、主客体等）…的 2.关于，对于 3.由…制成的 4.由于，因为 5.来自…的，从 6.（引出动词不定式的逻辑主语）用于 adj. +","example":"The door of the classroom is broken and needs repair. / 教室的门坏了，需要修理。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01305","word":"off","type":"介词","phonetic":"/ɔ(:)f/","meaning":"从…离开，脱离 adv.1.距，隔开 2.表分离，中断 3.表脱掉，除去，从身体拿掉 4.不工作，不上班 5.减价，打折","example":"The cup fell off the table and broke into pieces. / 杯子从桌上掉下来摔成了碎片。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01306","word":"off duty","type":"短语","phonetic":"","meaning":"下班","example":"The guard is off duty after eight in the evening. / 那名保安晚上八点后下班。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01307","word":"offer","type":"及物动词","phonetic":"/'ɔfə/","meaning":"提供, 提出 n. 提议，提供","example":"The company offered him a good job in the city. / 这家公司给他在城里提供了一份好工作。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01308","word":"office","type":"名词","phonetic":"/'ɔfis/","meaning":"1.办公室，办事处 2.处，局，厅, 行 3.政府机关，（英）部；（美）司，局","example":"My mother works in a small office near the station. / 我妈妈在车站附近的一间小办公室工作。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01309","word":"officer","type":"名词","phonetic":"/'ɔfisə/","meaning":"1.官员，办事员 2.军官","example":"The police officer helped the lost child find his mother. / 警察帮助走失的孩子找到了妈妈。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01310","word":"of itself","type":"短语","phonetic":"","meaning":"自行","example":"The old door closed of itself when the wind blew. / 风吹来时，那扇旧门自己关上了。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01311","word":"often","type":"副词","phonetic":"/'ɔ (:)fn/","meaning":"1.经常，常常 2.（短语中）how often 多久一次","example":"We often play basketball after class on the playground. / 我们下课后常在操场上打篮球。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01312","word":"oil","type":"名词","phonetic":"/ɔil/","meaning":"石油，油 vt.给…加润滑油","example":"The car needs oil and water before the long trip. / 长途旅行前，这辆车需要加机油和水。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01313","word":"okay / O.K. / OK","type":"形容词","phonetic":"","meaning":"/adv.好，行","example":"It is OK to ask your teacher when you need help. / 需要帮助时向老师提问是可以的。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01314","word":"old","type":"形容词","phonetic":"/əuld/","meaning":"1.年老的，老的 2．…岁的 3.古老的，陈旧的","example":"My grandfather still lives in the old house in the village. / 我爷爷还住在村里的那座老房子里。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01315","word":"on","type":"介词","phonetic":"/ɔn/","meaning":"1.在…上面 2.在…旁，靠近…3.向，朝着 4.在…时候 5.关于，论述 6.根据，靠 adv.1.向前，继续下去 2.在上，穿上 3.接通 4.（与 be, have 连用)","example":"The book on the desk belongs to my roommate. / 桌上的那本书是我室友的。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01316","word":"on board","type":"短语","phonetic":"","meaning":"在船（车，飞机）上","example":"All the passengers on board were asked to stay calm. / 船上的所有乘客都被要求保持冷静。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01317","word":"on business","type":"短语","phonetic":"","meaning":"因事，因公","example":"My father went to Beijing on business last Monday. / 我父亲上周一去北京出差。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01318","word":"once","type":"副词","phonetic":"/wʌns/","meaning":"1.一次，一回 2.曾经","example":"I have visited the science museum once before. / 我以前去过一次科学博物馆。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01319","word":"once in a while","type":"短语","phonetic":"","meaning":"偶尔","example":"We go to the cinema once in a while when we are free. / 有空的时候我们偶尔去看电影。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01320","word":"on condition that","type":"短语","phonetic":"","meaning":"如果","example":"You can borrow my bike on condition that you return it today. / 你可以借我的自行车，条件是今天归还。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01321","word":"on duty","type":"短语","phonetic":"","meaning":"值班，上班","example":"Two nurses are on duty during the whole night. / 两名护士整夜值班。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01322","word":"one","type":"数词","phonetic":"/wʌn/","meaning":"一个，一 adj.某一 one day 某天 pro.一个人，任何人","example":"One of my classmates comes from a small town in Sichuan. / 我的一位同学来自四川的一个小镇。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01323","word":"one after another","type":"短语","phonetic":"","meaning":"一个接一个","example":"The students came into the hall one after another. / 学生们一个接一个地走进大厅。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01324","word":"oneself","type":"代词","phonetic":"/wʌn'self/","meaning":"自己，自身","example":"One should learn to control oneself in difficult times. / 人应该学会在困难的时候控制自己。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01325","word":"only","type":"副词","phonetic":"/'əunli/","meaning":"仅仅，只不过 adj.惟一的 conj.只不过，但是，可是","example":"Only by working hard can we make real progress. / 只有努力工作，我们才能取得真正的进步。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01326","word":"on purpose","type":"短语","phonetic":"","meaning":"故意地","example":"He did not break the window on purpose, so do not blame him. / 他不是故意打破窗户的，别责怪他。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01327","word":"on the basis of","type":"短语","phonetic":"","meaning":"根据, 在… 的基础上","example":"The teacher judged our work on the basis of daily records. / 老师根据平时的记录来评价我们的作业。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01328","word":"on the contrary","type":"短语","phonetic":"","meaning":"正相反","example":"On the contrary, helping others can make us happier. / 相反，帮助别人能让我们更快乐。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01329","word":"on the ground(s) of","type":"短语","phonetic":"","meaning":"由于, 因为","example":"The match was put off on the grounds of heavy rain. / 由于大雨，比赛被推迟了。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01330","word":"on the spot","type":"短语","phonetic":"","meaning":"马上，立刻；当场；在现场；当机立断 v.玷污，弄脏；vt. 认出，发现","example":"The doctor arrived on the spot within ten minutes. / 医生十分钟内就赶到了现场。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01331","word":"on the whole","type":"短语","phonetic":"","meaning":"总的来说, 大体上","example":"On the whole, the plan is practical and worth trying. / 总的来说，这个计划切实可行，值得一试。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01332","word":"onto","type":"介词","phonetic":"/'ɔntu/","meaning":"到…之上，达于…之上","example":"The cat jumped onto the table and knocked over a cup. / 猫跳到桌子上，碰倒了一只杯子。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01333","word":"open","type":"及物动词","phonetic":"/'əupən/","meaning":"打开 vi.开放 adj. 1.开着的 2.开阔的，空旷的 3.敞开的，无遮盖的，露天的 4.开放营业的","example":"Please open your books and turn to page twenty. / 请打开你们的书，翻到第二十页。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01334","word":"operate","type":"及物动词","phonetic":"/'ɔpəreit/","meaning":"1.使运转，经营 2.动手术，开刀","example":"My uncle operates a small restaurant near the school. / 我叔叔在学校附近经营一家小餐馆。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01335","word":"operation","type":"名词","phonetic":"/ˌɔpə'reiʃən/","meaning":"运转，操作，手术","example":"The operation lasted three hours and went very well. / 手术持续了三个小时，进行得很顺利。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01336","word":"opinion","type":"名词","phonetic":"/ə'pinjən/","meaning":"意见，看法","example":"In my opinion, we should spend less time on our phones. / 在我看来，我们应该少花点时间看手机。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01337","word":"opposite","type":"形容词","phonetic":"/'ɔpəzit/","meaning":"1.对面的，相对的 2.相反的 n.反义词，相反的事物","example":"The library is on the opposite side of the road. / 图书馆在马路的对面。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01338","word":"or","type":"连词","phonetic":"/ɔ:/","meaning":"1.或，或者 2.（与 else 连用）否则，要不然 3（. 与 either 连用）either…or… 或者…或者，不论…还是…","example":"You can take the bus or walk to school every day. / 你每天可以坐公交或走路去学校。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01339","word":"orange","type":"名词","phonetic":"/'ɔrinʤ/","meaning":"柑，橘，橙（树）；橙黄色 adj.橙黄色的","example":"She bought two oranges and some apples at the market. / 她在市场上买了两个橙子和一些苹果。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01340","word":"order","type":"名词","phonetic":"/'ɔ:də/","meaning":"1.命令 2.次序，顺序 3.秩序 4.正常状态，整齐 5.定购，订单 6.目的 vt.命令；定购，定","example":"Please put the books in order before you leave the room. / 离开房间前请把书按顺序放好。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01341","word":"ordinary","type":"形容词","phonetic":"/'ɔ:dinəri/","meaning":"平凡的，普通的，一般的","example":"Although he is an ordinary student, he has a big dream. / 他虽是普通学生，却有着远大的梦想。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01342","word":"organization/-isation","type":"名词","phonetic":"/ɔrɡənaɪ'zeɪʃən/","meaning":"1.组织 2.机构，团体 organize/-ise vt.组织，创办","example":"She joined a student organization to help protect the environment. / 她加入了一个学生组织，参与环境保护。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01343","word":"or so","type":"短语","phonetic":"","meaning":"左右，大约","example":"We walked for an hour or so before we reached the village. / 我们走了大约一小时才到村里。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01344","word":"other","type":"形容词","phonetic":"/'ʌðə/","meaning":"另外的，其他的","example":"We should learn to help other people when they are in trouble. / 我们应该学会在别人有困难时伸出援手。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01345","word":"otherwise","type":"连词","phonetic":"/'ʌðəwaiz/","meaning":"否则，不然 adv.用其他方法，不同地","example":"Work harder, otherwise you will fall behind your classmates. / 再努力些，否则你会落后于同学。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01346","word":"ought","type":"动词","phonetic":"/ɔ:t/","meaning":"aux. 应该","example":"You ought to say sorry to your classmate right now. / 你现在应该向同学道歉。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01347","word":"our","type":"代词","phonetic":"/'auə/","meaning":"（we 的所有格）我们的","example":"Our classroom is bright and clean with big windows. / 我们的教室有大窗户，明亮又干净。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01348","word":"ours","type":"代词","phonetic":"/'auəz/","meaning":"(we 的物主代词)我们的","example":"This basketball is ours, and that one belongs to Class Two. / 这个篮球是我们的，那个是二班的。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01349","word":"ourselves","type":"代词","phonetic":"/'auə'selvz/","meaning":"1.我们自己 (we 的反身代词)2.我们亲自（用以强调）","example":"We should learn to take good care of ourselves. / 我们应该学会好好照顾自己。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01350","word":"out","type":"形容词","phonetic":"/aut/","meaning":"1. 在外, 向外 2. 显露出来 3. 熄灭, 尽, 完","example":"The lights went out and the whole room was dark. / 灯熄灭了，整个房间一片漆黑。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01351","word":"outdoor","type":"形容词","phonetic":"/aʊt'dɔ:/","meaning":"户外的；野外的","example":"Outdoor activities help students keep fit and relax after class. / 户外活动有助于学生课后健身和放松。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01352","word":"out of","type":"短语","phonetic":"","meaning":"1.在…外，向…之外 2.由于，出于 3.从…中 4.越出 5.丧失，失去 6.缺乏","example":"The little boy ran out of the room with a big smile. / 小男孩带着灿烂的笑容跑出了房间。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01353","word":"over","type":"介词","phonetic":"/'əuvə/","meaning":"1.在…上方，在…上面 2.越过 3.多于，…以上 4.在…期间 5.遍及，到处 adv.1.翻转过来 2.结束，完了 3.(越)过 4.在那边，向那边 5.太，过分 6.再，重复的","example":"The plane flew over the mountains and reached the city. / 飞机飞越群山，到达了这座城市。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01354","word":"overcoat","type":"名词","phonetic":"/'əuvəkəut/","meaning":"外套，大衣","example":"He put on his overcoat and walked into the cold wind. / 他穿上大衣，走进了寒风中。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01355","word":"oversea(s)","type":"形容词","phonetic":"/əʊvə(r)si:/","meaning":"海外的 adv.在海外，去海外","example":"Many students want to study overseas after graduation. / 许多学生想毕业后到海外留学。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01356","word":"own","type":"形容词","phonetic":"/əun/","meaning":"（属于）自己的；特有的 vt.有，拥有","example":"She has her own room with a small desk by the window. / 她有自己的房间，窗边有一张小书桌。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01357","word":"ox","type":"名词","phonetic":"/ɔks/","meaning":"公牛","example":"The ox pulled the heavy cart along the village road. / 那头牛沿着村路拉着沉重的车。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01358","word":"pacific","type":"形容词","phonetic":"/pə'sifik/","meaning":"1.和平的，平静的 2.太平洋的","example":"The Pacific Ocean covers a large part of the earth. / 太平洋覆盖了地球的很大一部分。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01359","word":"page","type":"名词","phonetic":"/peiʤ/","meaning":"页","example":"Please turn to page ten and read the passage aloud. / 请翻到第十页，大声朗读这段文章。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01360","word":"pain","type":"名词","phonetic":"/pein/","meaning":"痛，痛苦","example":"She felt a sharp pain in her back after the long trip. / 长途旅行后，她感到背部一阵剧痛。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01361","word":"paint","type":"名词","phonetic":"/peint/","meaning":"油漆，颜料 vt.1.给…上油漆 2（. 用颜料等）绘，画","example":"They painted the wall white before the new term began. / 新学期开始前，他们把墙刷成了白色。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01362","word":"painting","type":"名词","phonetic":"/'peintiŋ/","meaning":"1.上油漆，着色 2.绘画，图画","example":"The painting on the wall was drawn by a young student. / 墙上的那幅画是一个年轻学生画的。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01363","word":"pair","type":"名词","phonetic":"/pɛə/","meaning":"一对，一双 a pair of socks 一双袜子","example":"I bought a new pair of shoes for the new term. / 我为新学期买了一双新鞋。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01364","word":"palace","type":"名词","phonetic":"/'pælis/","meaning":"宫殿","example":"The old palace is now a popular place for visitors. / 这座古老的宫殿现在是游客喜爱的景点。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01365","word":"pale","type":"形容词","phonetic":"/peil/","meaning":"1.苍白的，灰白的 2.淡的，暗淡的","example":"She looked pale after staying up late for two nights. / 连续两晚熬夜后，她脸色苍白。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01366","word":"paper","type":"名词","phonetic":"/'peipə/","meaning":"1.纸 2.报纸 3.试卷 4.文章，论文 5. (pl.)官方文件","example":"The teacher handed out the test paper to every student. / 老师把试卷发给每个学生。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01367","word":"pardon","type":"及物动词","phonetic":"/'pɑ:dn/","meaning":"原谅，饶恕 n.原谅，饶恕","example":"Pardon me for being late this morning. / 请原谅我今天早上迟到了。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01368","word":"parent","type":"名词","phonetic":"/'pɛərənt/","meaning":"父亲，母亲，家长","example":"Every parent wants their child to grow up healthy and happy. / 每位家长都希望孩子健康快乐地成长。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01369","word":"park","type":"名词","phonetic":"/pɑ:k/","meaning":"公园 vt.停放","example":"We often walk in the park after dinner in summer. / 夏天晚饭后我们常在公园散步。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01370","word":"part","type":"名词","phonetic":"/pɑ:t/","meaning":"1.部分，局部 2.角色 3.一方，方面 4.零件 vt.（使）分开","example":"Reading is an important part of learning a foreign language. / 阅读是学习外语的重要部分。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01371","word":"particular","type":"形容词","phonetic":"/pə'tikjulə/","meaning":"1.特殊的，特别的 2.特定的，个别的 n.(pl.)细节","example":"On that particular morning, Lily found a strange box outside her door. / 就在那个特别的早晨，莉莉在门外发现了一个奇怪的箱子。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01372","word":"party","type":"名词","phonetic":"/'pɑ:ti/","meaning":"1.聚会 2.党派，政党","example":"Tom invited ten classmates to his birthday party on Saturday evening. / 汤姆邀请十位同学参加他周六晚上的生日聚会。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01373","word":"pass","type":"及物动词","phonetic":"/pɑ:s/","meaning":"1.经过，穿过 2.（使）及格，批准 3.度过，度（日）4.传递，传给","example":"Lily studied hard and passed the final English exam last term. / 莉莉努力学习，上学期通过了英语期末考试。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01374","word":"passage","type":"名词","phonetic":"/'pæsiʤ/","meaning":"1.通过，经过 2.通道 3.（一）段，（一）节","example":"Please read the passage again and answer the three questions below. / 请再读一遍这段文章，并回答下面的三个问题。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01375","word":"passenger","type":"名词","phonetic":"/'pæsinʤə/","meaning":"乘客，旅客","example":"The passenger asked the driver to stop near the school gate. / 那位乘客请司机在学校大门附近停车。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01376","word":"past","type":"介词","phonetic":"/pɑ:st/","meaning":"过，越过 n.过去 adj.过去的","example":"The old man walked past the park and turned left slowly. / 那位老人走过公园，然后慢慢向左转。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01377","word":"path","type":"名词","phonetic":"/pɑ:θ/","meaning":"1.小路，小径 2.路线，轨道","example":"A narrow path leads from our village to the river. / 一条小路从我们村子通向河边。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01378","word":"pause","type":"不及物动词","phonetic":"/pɔ:z/","meaning":"& n.中止，暂停","example":"The teacher paused for a moment before answering the difficult question. / 老师停顿了一下才回答那个难题。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01379","word":"pay","type":"及物动词","phonetic":"/pei/","meaning":"支付，付出","example":"He paid fifty yuan for the new dictionary yesterday afternoon. / 他昨天下午花五十元买了那本新词典。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01380","word":"pay attention to","type":"短语","phonetic":"","meaning":"注意, 关心","example":"Students should pay attention to the teacher in every class. / 学生在每节课上都应该注意听老师讲课。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01381","word":"peace","type":"名词","phonetic":"/pi:s/","meaning":"1.和平 2.平静，安宁","example":"Everyone in the village hopes for peace and a quiet life. / 村里每个人都希望和平与安宁的生活。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01382","word":"peaceful","type":"形容词","phonetic":"/'pi:sfəl/","meaning":"1.和平的 2.平静的，安宁的","example":"The small town becomes quiet and peaceful after ten at night. / 晚上十点以后，这个小镇变得安静而祥和。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01383","word":"pear","type":"名词","phonetic":"/pɛə/","meaning":"梨","example":"Mother put two sweet pears in my school bag this morning. / 今天早上妈妈往我书包里放了两个甜梨。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01384","word":"peasant","type":"名词","phonetic":"/'pezənt/","meaning":"农民","example":"The peasant works hard in the field from spring to autumn. / 这位农民从春天到秋天都在田里辛勤劳作。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01385","word":"pen","type":"名词","phonetic":"/pen/","meaning":"钢笔","example":"He borrowed a blue pen from me to sign his name. / 他向我借了一支蓝色的笔来签名。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01386","word":"pencil","type":"名词","phonetic":"/'pensl/","meaning":"铅笔","example":"The little girl drew a big house with her new pencil. / 小女孩用新铅笔画了一座大房子。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01387","word":"penny","type":"名词","phonetic":"/'peni/","meaning":"便士(pl. pence, pennies)","example":"She saved every penny to buy a gift for her mother. / 她把每一分钱都存起来给妈妈买礼物。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01388","word":"people","type":"名词","phonetic":"/'pi:pl/","meaning":"1.人，人们 2.人民，民众 3.民族（可数）","example":"Many people in the city like to walk in the park after dinner. / 城里很多人喜欢晚饭后到公园散步。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01389","word":"percent","type":"名词","phonetic":"/pə'sent/","meaning":"百分之…","example":"About sixty percent of the students in our class enjoy reading novels. / 我们班大约百分之六十的学生喜欢读小说。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01390","word":"perfect","type":"形容词","phonetic":"/'pə:fikt/","meaning":"1.完美的，无暇的 2.完全的，十足的 3.\\[语法\\]完成时","example":"Nobody is perfect, so we should learn from our mistakes. / 没有人是完美的，所以我们应该从错误中学习。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01391","word":"perhaps","type":"副词","phonetic":"/pə'hæps/","meaning":"也许，大概","example":"Perhaps the rain will stop before we leave the library. / 也许我们离开图书馆之前雨就会停。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01392","word":"period","type":"名词","phonetic":"/'piəriəd/","meaning":"1.时期，时代 2.学时，课时 3.周期","example":"We lived in a quiet village during that period of time. / 那段时期我们住在一个安静的村子里。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01393","word":"permit","type":"及物动词","phonetic":"/pə'mit/","meaning":"许可，允许 n.许可证","example":"The school does not permit students to use phones in class. / 学校不允许学生在课堂上使用手机。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01394","word":"person","type":"名词","phonetic":"/'pə:sn/","meaning":"1.人 2.本人，自身","example":"The first person to arrive at the meeting was our monitor. / 第一个到会场的人是我们班长。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01395","word":"personal","type":"形容词","phonetic":"/'pə:sənl/","meaning":"1.个人的，私人的 2.亲自的","example":"He never talks about his personal life with strangers. / 他从不和陌生人谈自己的私生活。","folder":"专升本词汇","level":"专升本","tags":["专升本","专升本高频"]},{"_id":"builtin-en-zsb-01396","word":"persuade","type":"及物动词","phonetic":"/pə(:)'sweid/","meaning":"1.说服，劝导(成功)2.(of)（使）相信","example":"Lily persuaded her father to give up smoking last year. / 去年莉莉说服父亲戒了烟。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01397","word":"pet","type":"名词","phonetic":"/pet/","meaning":"宠物，宠儿","example":"My little cousin keeps a white rabbit as a pet. / 我的小表弟养了一只白兔当宠物。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01398","word":"phone","type":"名词","phonetic":"/fəʊ̯n/","meaning":"电话；电话机 vt. 给…打电话","example":"Please call me on my phone when you reach the station. / 你到车站时请给我打电话。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01399","word":"photo(graph)","type":"名词","phonetic":"/'fəʊtəʊ/","meaning":"照片","example":"We took a photo in front of the old library building. / 我们在老图书馆楼前拍了一张照片。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01400","word":"phrase","type":"名词","phonetic":"/freiz/","meaning":"短语，词组 a noun phrase 名词短语","example":"The teacher explained this useful phrase to the whole class. / 老师向全班解释了这条有用的短语。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01401","word":"physics","type":"名词","phonetic":"/'fiziks/","meaning":"物理（学）","example":"Physics is my favourite subject because it explains everyday life. / 物理是我最喜欢的科目，因为它能解释日常生活。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01402","word":"piano","type":"名词","phonetic":"/pi'ænəu/","meaning":"钢琴","example":"She has played the piano for six years and enjoys it greatly. / 她弹钢琴已经六年了，并且非常喜欢。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01403","word":"pick","type":"及物动词","phonetic":"/pik/","meaning":"1.采摘，摘 2.挑选，选择 n.镐，鹤嘴锄","example":"The children went to the orchard to pick apples on Sunday. / 星期天孩子们去果园摘苹果。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01404","word":"pick out","type":"短语","phonetic":"","meaning":"1.挑选，拣出 2.辨认，辨别出","example":"It was hard to pick out my friend in the crowded square. / 在拥挤的广场上很难辨认出我的朋友。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01405","word":"pick up","type":"短语","phonetic":"","meaning":"1.拾起 2.增加，改进 3.（偶然）得到","example":"Please pick up your toys and put them in the box. / 请把你的玩具捡起来放进盒子里。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01406","word":"picnic","type":"名词","phonetic":"/'piknik/","meaning":"野餐 vi.去野餐","example":"Our class will have a picnic by the lake next Friday. / 我们班下星期五将在湖边野餐。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01407","word":"picture","type":"名词","phonetic":"/'pikʧə/","meaning":"1.画，图画 2.影片 3.美景 vt.画，描述","example":"There is a picture of my grandparents on the living room wall. / 客厅墙上有一张我祖父母的照片。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01408","word":"pie","type":"名词","phonetic":"/pai/","meaning":"馅饼","example":"My aunt made an apple pie for the family dinner. / 我姑姑为家庭聚餐做了一个苹果派。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01409","word":"piece","type":"名词","phonetic":"/pi:s/","meaning":"1.件，块，片 2.碎片，断片","example":"He cut the cake into six pieces and shared them. / 他把蛋糕切成六块分给大家。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01410","word":"pig","type":"名词","phonetic":"/pig/","meaning":"猪","example":"The farmer keeps twenty pigs and some chickens on his farm. / 这位农民在农场里养了二十头猪和一些鸡。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01411","word":"pile","type":"名词","phonetic":"/pail/","meaning":"堆 v. (up)堆积，堆","example":"A pile of old books lay in the corner of the room. / 房间角落里放着一堆旧书。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01412","word":"pin","type":"名词","phonetic":"/pɪn/","meaning":"1.钉，销，栓 2.大头针，别针 vt. (up)钉住，别住","example":"She used a pin to hold the paper flowers together. / 她用一枚别针把纸花固定在一起。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01413","word":"pink","type":"名词","phonetic":"/piŋk/","meaning":"粉红色, 桃红色 adj. 粉红色的","example":"Lily wore a pink dress to her sister's wedding. / 莉莉穿着一条粉红色的裙子去参加姐姐的婚礼。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01414","word":"pioneer","type":"名词","phonetic":"/paiə'niə/","meaning":"先驱，倡导者","example":"He was a pioneer in the study of modern Chinese medicine. / 他是现代中医研究领域的先驱。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01415","word":"pipe","type":"名词","phonetic":"/paip/","meaning":"1.管子 2.烟斗","example":"The worker repaired the water pipe under the kitchen floor. / 工人修好了厨房地板下面的水管。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01416","word":"pity","type":"及物动词","phonetic":"/'piti/","meaning":"（觉得）可怜 n.1.憾事 2.怜悯","example":"I really pity those children who have no chance to study. / 我真的很可怜那些没有机会读书的孩子。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01417","word":"place","type":"名词","phonetic":"/pleis/","meaning":"1.地方，地点 2.名次 3.地位，职位 vt.1.放置 2.凭记忆或经验辨认（某人，某物）3.投（资），订（货）","example":"This quiet place is perfect for reading on a warm afternoon. / 这个安静的地方非常适合在温暖的午后读书。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01418","word":"plain","type":"形容词","phonetic":"/plein/","meaning":"1.明白的，清晰的 2.朴素的，平常的 n.平原，旷野","example":"Her explanation was plain enough for everyone to understand. / 她的解释很清楚，人人都能听懂。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01419","word":"plan","type":"名词","phonetic":"/plæn/","meaning":"1.计划，规划 2.平面图，设计图 vt.计划","example":"We made a careful plan for the summer holiday last week. / 上星期我们为暑假做了周密的计划。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01420","word":"plane","type":"名词","phonetic":"/plein/","meaning":"1.飞机 2.平面，水平面","example":"Our plane will take off at eight in the morning tomorrow. / 我们的飞机明天早上八点起飞。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01421","word":"plant","type":"名词","phonetic":"/plɑ:nt/","meaning":"1.植物，作物 2.工厂 3.装置 vt.栽种，播种","example":"These green plants need water and sunlight every day. / 这些绿色植物每天都需要水和阳光。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01422","word":"plate","type":"名词","phonetic":"/pleit/","meaning":"1.金属板，片 2.盘子，盆子 vt.电镀","example":"She put the fish on a white plate and served it. / 她把鱼放在一个白盘子里端上桌。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01423","word":"play","type":"动词","phonetic":"/plei/","meaning":"1.玩，游戏 2.演奏 3.扮演 n.1.游戏，比赛 2.剧本，戏剧","example":"The children play games on the playground after school. / 孩子们放学后在操场上做游戏。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01424","word":"play an important role in…","type":"短语","phonetic":"","meaning":"在…中扮演重要角色或起很重要的作用","example":"Sports play an important role in keeping students healthy and happy. / 体育运动在让学生保持健康快乐方面起着重要作用。","folder":"专升本词汇","level":"专升本","tags":["专升本","短语"]},{"_id":"builtin-en-zsb-01425","word":"player","type":"名词","phonetic":"/'pleiə/","meaning":"1.做游戏的人，比赛者 2.演员，演奏者","example":"Our best player scored two goals in the second half. / 我们最好的球员在下半场进了两个球。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01426","word":"playground","type":"名词","phonetic":"/'pleɪɡraʊnd/","meaning":"运动场，游乐场","example":"The playground is full of laughter during the morning break. / 上午课间休息时，操场上充满了笑声。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01427","word":"pleasant","type":"形容词","phonetic":"/'pleznt/","meaning":"令人愉快的，舒适的","example":"We spent a pleasant afternoon walking along the river bank. / 我们在河岸边散步，度过了一个愉快的下午。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01428","word":"please","type":"及物动词","phonetic":"/pli:z/","meaning":"请 v. (使)喜欢, 中（…的）意","example":"The little boy tried hard to please his strict grandfather. / 小男孩努力想让严厉的祖父高兴。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01429","word":"pleasure","type":"名词","phonetic":"/'pleʒə/","meaning":"1.愉快，快乐 2.乐事，乐趣","example":"It is a great pleasure to meet you here today. / 今天在这里见到你是一件非常愉快的事。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01430","word":"plenty","type":"名词","phonetic":"/'plenti/","meaning":"丰富，大量","example":"There is plenty of time for us to finish the work. / 我们有充足的时间完成这项工作。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01431","word":"plow/plough","type":"名词","phonetic":"/plau/","meaning":"犁 v.耕，犁","example":"The farmer used a plow to turn over the heavy soil. / 农民用犁翻耕沉重的土地。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01432","word":"pocket","type":"名词","phonetic":"/'pɔkit/","meaning":"袋子，小袋 vt.把…装入袋内","example":"He put the ticket into his coat pocket and left. / 他把票放进外套口袋，然后离开了。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01433","word":"point","type":"名词","phonetic":"/pɔint/","meaning":"1.尖，尖端 2.点，小数点 3.条款，细目 4.分（数），得分 5.要点，论点 v.1.(at, to)指向，表明 2. (out)指出","example":"The main point of his speech was to protect the environment. / 他演讲的要点是保护环境。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01434","word":"police","type":"名词","phonetic":"/pə'li:s/","meaning":"(the police)警察当局，警方","example":"The police arrived quickly and helped the lost child. / 警察很快赶到，帮助了那个走失的孩子。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01435","word":"policeman","type":"名词","phonetic":"/pə'li:smən/","meaning":"警察","example":"A policeman showed us the way to the railway station. / 一位警察给我们指了去火车站的路。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01436","word":"polite","type":"形容词","phonetic":"/pə'lait/","meaning":"1.有礼貌的，客气的 2.有教养的，文雅的","example":"It is polite to say thank you when others help you. / 别人帮助你时说声谢谢是有礼貌的。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01437","word":"political","type":"形容词","phonetic":"/pə'litikəl/","meaning":"政治（上）的","example":"They often discuss social and political problems in class. / 他们经常在课上讨论社会和政治问题。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01438","word":"pool","type":"名词","phonetic":"/pu:l/","meaning":"1.水池，游泳池 2.集中使用的资金、物资、服务等 vt.向共同基金提供（金钱、资源等）","example":"The children swim in the pool every afternoon in summer. / 夏天孩子们每天下午都在游泳池里游泳。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01439","word":"poor","type":"形容词","phonetic":"/puə/","meaning":"1.贫穷的，穷的 2.可怜的 3.贫乏的，贫瘠的","example":"The poor family received warm help from their neighbours. / 这个贫困的家庭得到了邻居们的热情帮助。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01440","word":"popular","type":"形容词","phonetic":"/'pɔpjulə/","meaning":"流行的，通俗的","example":"Basketball is very popular among the students in our school. / 篮球在我们学校的学生中很受欢迎。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01441","word":"population","type":"名词","phonetic":"/ˌpɔpju'leiʃən/","meaning":"人口","example":"The population of this small town has grown very fast. / 这个小镇的人口增长得很快。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01442","word":"pork","type":"名词","phonetic":"/pɔ:k/","meaning":"猪肉","example":"My mother cooked pork with potatoes for supper last night. / 昨晚妈妈做了土豆烧猪肉当晚饭。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01443","word":"port","type":"名词","phonetic":"/pɔ:t/","meaning":"港，港口 a fishing port 渔港","example":"The ship stayed in the port for two days because of the storm. / 因为暴风雨，那艘船在港口停了两天。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01444","word":"position","type":"名词","phonetic":"/pə'zɪʃ(ə)n/","meaning":"1.位置，方位 2.职位，职务 3.形势，状况 4.见解，立场","example":"He found a good position in a company after graduation. / 毕业后他在一家公司找到了一个好职位。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01445","word":"possible","type":"形容词","phonetic":"/'pɔsəbl/","meaning":"1.可能的 2.合理的，允许的","example":"It is possible for us to finish the task before Friday. / 我们有可能在星期五之前完成这项任务。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01446","word":"possibly","type":"副词","phonetic":"/'pɔsəbli/","meaning":"1.尽可能的 2.也许","example":"She will possibly arrive late because of the heavy traffic. / 因为交通拥堵，她可能会迟到。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01447","word":"post","type":"及物动词","phonetic":"/pəust/","meaning":"1.邮寄 2.贴出 n.1.邮政，邮件 2.柱，标杆 3.职位，岗位","example":"Please post this letter for me when you go out. / 你出去时请帮我把这封信寄了。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01448","word":"postcard","type":"名词","phonetic":"/'pəustkɑ:d/","meaning":"明信片","example":"Lily sent me a beautiful postcard from the seaside. / 莉莉从海边给我寄来一张漂亮的明信片。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01449","word":"pot","type":"名词","phonetic":"/pɔt/","meaning":"罐，壶","example":"There is a pot of hot tea on the kitchen table. / 厨房桌子上有一壶热茶。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01450","word":"potato","type":"名词","phonetic":"/pə'teitəu/","meaning":"土豆","example":"He planted potatoes and tomatoes in his small garden. / 他在自己的小菜园里种了土豆和西红柿。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01451","word":"pound","type":"名词","phonetic":"/paund/","meaning":"1.磅；一磅的量 2.英镑 vi. (不断地)敲打;连续猛击 vt. 捣碎","example":"This bag of rice weighs about five pounds on the old scale. / 这袋大米在老秤上大约重五磅。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01452","word":"power","type":"名词","phonetic":"/'pauə/","meaning":"1.权力，政权 2.能力，精力 3.功率，动力 4.(数字)乘方","example":"Knowledge gives young people the power to change their future. / 知识赋予年轻人改变未来的力量。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01453","word":"practical","type":"形容词","phonetic":"/'præktikəl/","meaning":"1.实际的，实践的 2.实用的，应用的 3.有实际经验的","example":"We need a practical method to solve this daily problem. / 我们需要一个实用的方法来解决这个日常问题。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01454","word":"practice","type":"名词","phonetic":"/'præktis/","meaning":"1.练习，实习 2.实践，实际","example":"Daily practice is the best way to improve your spoken English. / 每天练习是提高英语口语的最好方法。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01455","word":"practise/-ice","type":"动词","phonetic":"/'præktɪs/","meaning":"1.练习，实习 2.实践，实行","example":"You should practise speaking English for twenty minutes every day. / 你应该每天练习说英语二十分钟。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01456","word":"praise","type":"及物动词","phonetic":"/preiz/","meaning":"赞扬，歌颂 n.赞扬，赞美的话","example":"The teacher praised Tom for his careful homework. / 老师表扬了汤姆作业认真。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01457","word":"prefer","type":"及物动词","phonetic":"/pri'fə:/","meaning":"(to) 更喜欢；宁愿","example":"I prefer walking to school because it keeps me healthy. / 我更喜欢步行上学，因为这让我保持健康。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01458","word":"prepare","type":"动词","phonetic":"/pri'pɛə/","meaning":"准备，预备","example":"She is preparing for the coming English examination these days. / 这些天她正在为即将到来的英语考试做准备。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01459","word":"present","type":"形容词","phonetic":"/pri'zent/","meaning":"1. 出席的；到场的 2.现在的，目前的 n.1.现在；目前 2.礼物；礼品 vt.1.赠予；呈现 2.提出；呈交","example":"All the students were present at the meeting this morning. / 今天上午所有学生都出席了会议。","folder":"专升本词汇","level":"专升本","tags":["专升本"]},{"_id":"builtin-en-zsb-01460","word":"president","type":"名词","phonetic":"/'prezidənt/","meaning":"1. 总统 2. 会长；校长","example":"The president of our university gave a short speech. / 我们大学的校长作了一个简短的讲话。","folder":"专升本词汇","level":"专升本","tags":["专升本"]}]);
